package org.apache.flink.types;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link Record#unionFields(Record)}. */
class RecordUnionFieldsTests {

    @Test
    void thisRecordValueTakesPrecedenceOverOtherRecordValue() {
        final Record record = new Record(new IntValue(1), new StringValue("this"));
        final Record other = new Record(new IntValue(2), new StringValue("other"));

        record.unionFields(other);

        assertThat(record.getNumFields()).isEqualTo(2);
        assertThat(record.getField(0, IntValue.class).getValue()).isEqualTo(1);
        assertThat(record.getField(1, StringValue.class).toString()).isEqualTo("this");
    }

    @Test
    void otherRecordValueFillsNullFieldAndNullRemainsNullWhenBothAreNull() {
        final Record record = new Record(3);
        record.setField(0, null);
        final Record other = new Record(new IntValue(7), null);
        other.setNumFields(3);

        record.unionFields(other);

        assertThat(record.getNumFields()).isEqualTo(3);
        assertThat(record.getField(0, IntValue.class).getValue()).isEqualTo(7);
        assertThat(record.getField(1, IntValue.class)).isNull();
        assertThat(record.getField(2, IntValue.class)).isNull();
    }

    @Test
    void unionUsesTheLargerNumberOfFieldsAndPreservesTrailingValues() {
        final Record record = new Record(new IntValue(1));
        final Record other = new Record(3);
        other.setField(1, new StringValue("middle"));
        other.setField(2, new IntValue(3));

        record.unionFields(other);

        assertThat(record.getNumFields()).isEqualTo(3);
        assertThat(record.getField(0, IntValue.class).getValue()).isEqualTo(1);
        assertThat(record.getField(1, StringValue.class).toString()).isEqualTo("middle");
        assertThat(record.getField(2, IntValue.class).getValue()).isEqualTo(3);
    }

    @Test
    void unionHandlesSerializedAndModifiedRecordsTogether() {
        final Record record = new Record(new IntValue(1), new StringValue("old"));
        final Record other = new Record(new IntValue(2), new StringValue("other"));
        record.updateBinaryRepresenation();
        other.updateBinaryRepresenation();
        record.setField(0, null);
        record.setField(1, null);
        other.setField(1, new StringValue("new"));

        record.unionFields(other);

        assertThat(record.getField(0, IntValue.class).getValue()).isEqualTo(2);
        assertThat(record.getField(1, StringValue.class).toString()).isEqualTo("new");
    }
}

