package org.apache.flink.api.java.typeutils;

import org.apache.flink.api.common.typeinfo.BasicTypeInfo;
import org.apache.flink.api.common.typeinfo.TypeInformation;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;

import static org.assertj.core.api.Assertions.assertThat;

class TypeExtractorAnalyzePojoTests {

    private final TypeExtractor typeExtractor = new TypeExtractor();

    @Test
    void analyzesPublicPojoFieldsAndTheirTypes() {
        TypeInformation<PublicPojo> typeInformation = analyze(PublicPojo.class);

        assertThat(typeInformation).isInstanceOf(PojoTypeInfo.class);
        PojoTypeInfo<PublicPojo> pojoTypeInfo = (PojoTypeInfo<PublicPojo>) typeInformation;
        assertThat(pojoTypeInfo.getTypeClass()).isEqualTo(PublicPojo.class);
        assertThat(pojoTypeInfo.getFieldNames()).containsExactly("number", "text");
        assertThat(pojoTypeInfo.getTypeAt("number")).isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(pojoTypeInfo.getTypeAt("text")).isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void returnsGenericTypeInfoForNonPublicClasses() {
        TypeInformation<PackagePrivatePojo> typeInformation = analyze(PackagePrivatePojo.class);

        assertThat(typeInformation).isInstanceOf(GenericTypeInfo.class);
        assertThat(typeInformation.getTypeClass()).isEqualTo(PackagePrivatePojo.class);
    }

    @Test
    void returnsGenericTypeInfoForClassesWithoutFields() {
        TypeInformation<EmptyPojo> typeInformation = analyze(EmptyPojo.class);

        assertThat(typeInformation).isInstanceOf(GenericTypeInfo.class);
        assertThat(typeInformation.getTypeClass()).isEqualTo(EmptyPojo.class);
    }

    @Test
    void returnsNullWhenAFieldIsNotAValidPojoField() {
        TypeInformation<InvalidFieldPojo> typeInformation = analyze(InvalidFieldPojo.class);

        assertThat(typeInformation).isNull();
    }

    @Test
    void returnsNullWhenCustomSerializationMethodsAreDeclared() {
        TypeInformation<CustomSerializationPojo> typeInformation =
                analyze(CustomSerializationPojo.class);

        assertThat(typeInformation).isNull();
    }

    @Test
    void returnsNullWhenDefaultConstructorIsMissing() {
        TypeInformation<MissingDefaultConstructorPojo> typeInformation =
                analyze(MissingDefaultConstructorPojo.class);

        assertThat(typeInformation).isNull();
    }

    @SuppressWarnings("unchecked")
    private <T> TypeInformation<T> analyze(Class<T> clazz) {
        return typeExtractor.analyzePojo(clazz, new ArrayList<>(), null, null);
    }

    public static class PublicPojo {
        public int number;
        public String text;

        public PublicPojo() {}
    }

    static class PackagePrivatePojo {
        public int number;

        public PackagePrivatePojo() {}
    }

    public static class EmptyPojo {
        public EmptyPojo() {}
    }

    public static class InvalidFieldPojo {
        private int number;

        public InvalidFieldPojo() {}
    }

    public static class CustomSerializationPojo {
        public int number;

        public CustomSerializationPojo() {}

        private void writeObject(java.io.ObjectOutputStream output) {}
    }

    public static class MissingDefaultConstructorPojo {
        public int number;

        public MissingDefaultConstructorPojo(int number) {
            this.number = number;
        }
    }
}

