package org.apache.flink.fs.s3native;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.configuration.CoreOptions;
import org.apache.flink.configuration.IllegalConfigurationException;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.net.URI;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class NativeS3FileSystemFactoryCreateTests {

    private static final URI S3_URI = URI.create("s3://test-bucket/path");

    @Test
    void createUsesConfiguredValues() throws Exception {
        Configuration configuration = baseConfiguration();
        configuration.set(NativeS3FileSystemFactory.ACCESS_KEY, "access-key");
        configuration.set(NativeS3FileSystemFactory.SECRET_KEY, "secret-key");
        configuration.set(NativeS3FileSystemFactory.REGION, "eu-west-1");
        configuration.set(NativeS3FileSystemFactory.ENDPOINT, "http://localhost:9000");
        configuration.set(NativeS3FileSystemFactory.PATH_STYLE_ACCESS, true);
        configuration.set(NativeS3FileSystemFactory.USE_ASYNC_OPERATIONS, false);
        configuration.set(NativeS3FileSystemFactory.READ_BUFFER_SIZE, 512 * 1024);
        configuration.set(NativeS3FileSystemFactory.PART_UPLOAD_MIN_SIZE, 8L * 1024 * 1024);
        configuration.set(NativeS3FileSystemFactory.MAX_CONCURRENT_UPLOADS, 3);
        configuration.set(NativeS3FileSystemFactory.DELETE_BATCH_ENABLED, false);
        configuration.set(NativeS3FileSystemFactory.SSE_TYPE, "sse-kms");
        configuration.set(NativeS3FileSystemFactory.SSE_KMS_KEY_ID, "alias/test-key");

        NativeS3FileSystem fileSystem = create(configuration);
        S3ClientProvider clientProvider = fileSystem.getClientProvider();

        assertThat(fileSystem.getUri()).isEqualTo(S3_URI);
        assertThat(fileSystem.getEntropyInjectionKey()).isNull();
        assertThat(fileSystem.isDeleteBatchEnabled()).isFalse();
        assertThat(fileSystem.getFsCloseTimeout())
                .isEqualTo(NativeS3FileSystemFactory.FS_CLOSE_TIMEOUT.defaultValue());
        assertThat(clientProvider.getRegion()).isEqualTo("eu-west-1");
        assertThat(clientProvider.getEndpoint()).isEqualTo("http://localhost:9000");
        assertThat(clientProvider.isPathStyleAccess()).isTrue();
        assertThat(clientProvider.getCredentialsProvider()).isNotNull();
        assertThat(clientProvider.getEncryptionConfig().getEncryptionType())
                .isEqualTo(S3EncryptionConfig.EncryptionType.SSE_KMS);
        assertThat(clientProvider.getEncryptionConfig().getKmsKeyId()).isEqualTo("alias/test-key");

        fileSystem.closeAsync().join();
    }

    @Test
    void createAppliesBucketSpecificOverrides() throws Exception {
        Configuration configuration = baseConfiguration();
        configuration.set(NativeS3FileSystemFactory.REGION, "us-east-1");
        configuration.set(NativeS3FileSystemFactory.PATH_STYLE_ACCESS, false);
        configuration.setString("s3.bucket.test-bucket.region", "ap-southeast-2");
        configuration.setString("s3.bucket.test-bucket.endpoint", "http://minio:9000");
        configuration.setString("s3.bucket.test-bucket.path-style-access", "true");
        configuration.setString("s3.bucket.test-bucket.delete.batch.enabled", "false");

        NativeS3FileSystem fileSystem = create(configuration);
        S3ClientProvider clientProvider = fileSystem.getClientProvider();

        assertThat(clientProvider.getRegion()).isEqualTo("ap-southeast-2");
        assertThat(clientProvider.getEndpoint()).isEqualTo("http://minio:9000");
        assertThat(clientProvider.isPathStyleAccess()).isTrue();
        assertThat(fileSystem.isDeleteBatchEnabled()).isFalse();

        fileSystem.closeAsync().join();
    }

    @Test
    void createRejectsMissingBucketName() {
        NativeS3FileSystemFactory factory = new NativeS3FileSystemFactory();
        factory.configure(baseConfiguration());

        assertThatThrownBy(() -> factory.create(URI.create("s3:///path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("missing or empty bucket name");
    }

    @Test
    void createRejectsInvalidEntropyConfiguration() {
        Configuration configuration = baseConfiguration();
        configuration.set(NativeS3FileSystemFactory.ENTROPY_INJECT_KEY_OPTION, "invalid#key");

        assertThatThrownBy(() -> create(configuration))
                .isInstanceOf(IllegalConfigurationException.class)
                .hasMessageContaining("Invalid character in entropy injection key");
    }

    @Test
    void createRejectsPartSizeBelowS3Minimum() {
        Configuration configuration = baseConfiguration();
        configuration.set(
                NativeS3FileSystemFactory.PART_UPLOAD_MIN_SIZE,
                NativeS3FileSystemFactory.S3_MULTIPART_MIN_PART_SIZE - 1);

        assertThatIllegalArgumentException()
                .isThrownBy(() -> create(configuration))
                .withMessageContaining("must be at least 5MB");
    }

    private static Configuration baseConfiguration() {
        Configuration configuration = new Configuration();
        configuration.set(CoreOptions.TMP_DIRS, System.getProperty("java.io.tmpdir"));
        configuration.set(NativeS3FileSystemFactory.METRICS_ENABLED, false);
        configuration.set(NativeS3FileSystemFactory.BULK_COPY_ENABLED, false);
        configuration.set(NativeS3FileSystemFactory.REGION, "us-east-1");
        configuration.set(NativeS3FileSystemFactory.ENDPOINT, "http://localhost:9000");
        configuration.set(
                NativeS3FileSystemFactory.AWS_CREDENTIALS_PROVIDER, "AnonymousCredentialsProvider");
        return configuration;
    }

    private static NativeS3FileSystem create(Configuration configuration) throws IOException {
        NativeS3FileSystemFactory factory = new NativeS3FileSystemFactory();
        factory.configure(configuration);
        return (NativeS3FileSystem) factory.create(S3_URI);
    }
}

