                        new org.apache.flink.table.types.logical.BigIntType(),
                        PrimitiveType.PrimitiveTypeName.INT64,
                        HeapLongVector.class),
                Arguments.of(
                        "float",
                        new org.apache.flink.table.types.logical.FloatType(),
                        PrimitiveType.PrimitiveTypeName.FLOAT,
