        WritableColumnVector vector =
                createWritableColumnVector(
                        BATCH_SIZE,
                        fieldType,
                        type,
                        List.of(descriptor(new String[] {"value"}, type)),
                        0);
        assertThat(vector).isInstanceOf(expectedClass);
    }

    private static Type primitiveType(
            String name, PrimitiveType.PrimitiveTypeName typeName, OriginalType originalType) {
        return primitiveType(name, typeName, originalType, 0, 0);
    }

    private static Type primitiveType(
            String name,
            PrimitiveType.PrimitiveTypeName typeName,
            OriginalType originalType,
            int precision,
            int scale) {
        Types.PrimitiveBuilder<PrimitiveType> builder =
                Types.primitive(typeName, Type.Repetition.OPTIONAL);
        if (originalType != null) {
            builder.as(originalType).precision(precision).scale(scale);
        }
        return builder.named(name);
