/** Tests for {@link ParquetSplitReaderUtil#createVectorFromConstant}. */
class ParquetSplitReaderUtilCreateVectorFromConstantTests {

    private static final int BATCH_SIZE = 3;

    @Test
    void testByteAndStringConstantsAreRepeated() {
        BytesColumnVector stringVector =
                (BytesColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new VarCharType(20), "flink", BATCH_SIZE);
        BytesColumnVector binaryVector =
                (BytesColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new VarBinaryType(20), new byte[] {1, 2, 3}, BATCH_SIZE);

        for (int row = 0; row < BATCH_SIZE; row++) {
            assertThat(stringVector.getBytes(row).getBytes()).containsExactly("flink".getBytes());
            assertThat(binaryVector.getBytes(row).getBytes()).containsExactly(1, 2, 3);
        }
    }

    @Test
    void testPrimitiveConstantsAreRepeated() {
        BooleanColumnVector booleanVector =
                (BooleanColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new BooleanType(), true, BATCH_SIZE);
        ByteColumnVector byteVector =
                (ByteColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new TinyIntType(), 129, BATCH_SIZE);
        ShortColumnVector shortVector =
                (ShortColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new SmallIntType(), 32769, BATCH_SIZE);
        IntColumnVector intVector =
                (IntColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new IntType(), 123456, BATCH_SIZE);
        LongColumnVector longVector =
                (LongColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new BigIntType(), 1234567890123L, BATCH_SIZE);
        FloatColumnVector floatVector =
                (FloatColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new FloatType(), 1.25f, BATCH_SIZE);
        DoubleColumnVector doubleVector =
                (DoubleColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new DoubleType(), 2.5d, BATCH_SIZE);

        for (int row = 0; row < BATCH_SIZE; row++) {
            assertThat(booleanVector.getBoolean(row)).isTrue();
            assertThat(byteVector.getByte(row)).isEqualTo((byte) 129);
            assertThat(shortVector.getShort(row)).isEqualTo((short) 32769);
            assertThat(intVector.getInt(row)).isEqualTo(123456);
            assertThat(longVector.getLong(row)).isEqualTo(1234567890123L);
            assertThat(floatVector.getFloat(row)).isEqualTo(1.25f);
            assertThat(doubleVector.getDouble(row)).isEqualTo(2.5d);
        }
    }

    @Test
    void testDecimalConstantsUseExpectedRepresentation() {
        assertDecimal(new DecimalType(9, 2), new BigDecimal("1234567.89"), 123456789L);
        assertDecimal(
                new DecimalType(18, 3), new BigDecimal("123456789012345.678"), 123456789012345678L);
        assertDecimalBytes(new DecimalType(20, 4), new BigDecimal("1234567890123456.7890"));
    }

    @Test
    void testDateAndTimestampConstantsAreConverted() {
        IntColumnVector dateVector =
                (IntColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new DateType(), LocalDate.of(2024, 1, 2), BATCH_SIZE);
        TimestampColumnVector timestampVector =
                (TimestampColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(
                                new TimestampType(6),
                                LocalDateTime.of(2024, 1, 2, 3, 4, 5, 678901234),
                                BATCH_SIZE);

        for (int row = 0; row < BATCH_SIZE; row++) {
            assertThat(dateVector.getInt(row)).isEqualTo(19724);
            assertThat(timestampVector.getTimestamp(row, 6))
                    .isEqualTo(
                            TimestampData.fromLocalDateTime(
                                    LocalDateTime.of(2024, 1, 2, 3, 4, 5, 678901234)));
        }
    }

    @Test
    void testNullConstantsFillEveryRowWithNull() {
        for (org.apache.flink.table.types.logical.LogicalType type :
                Arrays.asList(
                        new VarCharType(20),
                        new BooleanType(),
                        new IntType(),
                        new DecimalType(9, 2),
                        new DateType(),
                        new TimestampType(6))) {
            ColumnVector vector =
                    ParquetSplitReaderUtil.createVectorFromConstant(type, null, BATCH_SIZE);
            for (int row = 0; row < BATCH_SIZE; row++) {
                assertThat(vector.isNullAt(row)).isTrue();
            }
        }
    }

    @Test
    void testUnsupportedTypeIsRejected() {
        assertThatThrownBy(
                        () ->
                                ParquetSplitReaderUtil.createVectorFromConstant(
                                        new LocalZonedTimestampType(6), null, BATCH_SIZE))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("Unsupported type");
    }

    private static void assertDecimal(
            DecimalType type, BigDecimal value, long expectedUnscaledValue) {
        DecimalColumnVector vector =
                (DecimalColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(type, value, BATCH_SIZE);
        for (int row = 0; row < BATCH_SIZE; row++) {
            assertThat(
                            vector.getDecimal(row, type.getPrecision(), type.getScale())
                                    .toUnscaledLong())
                    .isEqualTo(expectedUnscaledValue);
        }
    }

    private static void assertDecimalBytes(DecimalType type, BigDecimal value) {
        DecimalColumnVector vector =
                (DecimalColumnVector)
                        ParquetSplitReaderUtil.createVectorFromConstant(type, value, BATCH_SIZE);
        for (int row = 0; row < BATCH_SIZE; row++) {
            assertThat(vector.getDecimal(row, type.getPrecision(), type.getScale()).toBigDecimal())
                    .isEqualByComparingTo(value);
        }
    }
