    @Test
    void convertsStringsAndPreservesAlreadyInternalValues() {
        StringData internal = StringData.fromString("internal");

        assertThat(InternalTypeConverter.toInternal("value", new VarCharType()))
                .isEqualTo(StringData.fromString("value"));
        assertThat(InternalTypeConverter.toInternal(internal, new VarCharType()))
                .isSameAs(internal);
        assertThat(InternalTypeConverter.toInternal(42, new IntType())).isEqualTo(42);
        assertThat(InternalTypeConverter.toInternal(null, new IntType())).isNull();
    }

    @Test
    void convertsDecimalsFromExternalRepresentations() {
        DecimalType type = new DecimalType(10, 2);
        BigDecimal value = new BigDecimal("12.34");

        assertThat(((DecimalData) InternalTypeConverter.toInternal(value, type)).toBigDecimal())
                .isEqualByComparingTo(value);
        assertThat(
                        ((DecimalData)
                                        InternalTypeConverter.toInternal(
                                                ByteBuffer.wrap(new byte[] {0x04, (byte) 0xd2}),
                                                type))
                                .toBigDecimal())
                .isEqualByComparingTo(value);
        assertThat(
                        ((DecimalData)
                                        InternalTypeConverter.toInternal(
                                                new byte[] {0x04, (byte) 0xd2}, type))
                                .toBigDecimal())
                .isEqualByComparingTo(value);
    }

    @Test
    void convertsDatesAndTimestamps() {
        LocalDate date = LocalDate.of(2024, 1, 2);
        Instant instant = Instant.parse("2024-01-02T03:04:05.006Z");
        LocalDateTime localDateTime = LocalDateTime.of(2024, 1, 2, 3, 4, 5, 6_000_000);
        Timestamp timestamp = Timestamp.from(instant);

        assertThat(InternalTypeConverter.toInternal(date, new DateType())).isEqualTo(19724);
        assertThat(InternalTypeConverter.toInternal(java.sql.Date.valueOf(date), new DateType()))
                .isEqualTo(19724);
        assertThat(InternalTypeConverter.toInternal(instant, new TimestampType()))
                .isEqualTo(TimestampData.fromInstant(instant));
        assertThat(InternalTypeConverter.toInternal(localDateTime, new TimestampType()))
                .isEqualTo(TimestampData.fromLocalDateTime(localDateTime));
        assertThat(InternalTypeConverter.toInternal(timestamp, new TimestampType()))
                .isEqualTo(TimestampData.fromTimestamp(timestamp));
    }

    @Test
    void convertsBinaryByteBuffersWithoutChangingTheirLogicalBytes() {
        ByteBuffer value = ByteBuffer.wrap(new byte[] {1, 2, 3});
        value.position(1);

        assertThat(InternalTypeConverter.toInternal(value, new BinaryType()))
                .isEqualTo(new byte[] {2, 3});
    }

    @Test
    void convertsNestedArraysRowsMapsAndMultisetsRecursively() {
        RowType rowType = RowType.of(new VarCharType(), new IntType());
        ArrayType arrayType = new ArrayType(new VarCharType());
        MapType mapType = new MapType(new VarCharType(), new IntType());

        Row sourceRow = Row.withPositions(RowKind.UPDATE_AFTER, 2);
        sourceRow.setField(0, "name");
        sourceRow.setField(1, 7);
        GenericRowData row = (GenericRowData) InternalTypeConverter.toInternal(sourceRow, rowType);
        GenericArrayData array =
                (GenericArrayData)
                        InternalTypeConverter.toInternal(new Object[] {"a", "b"}, arrayType);
        GenericMapData map =
                (GenericMapData) InternalTypeConverter.toInternal(Map.of("one", 1), mapType);
        GenericMapData entries =
