                        InternalTypeConverter.toInternal(
                                List.of(new AbstractMap.SimpleEntry<>("two", 2)), mapType);
        GenericMapData multiset =
                (GenericMapData)
                        InternalTypeConverter.toInternal(
                                Map.of("item", 3), new MultisetType(new VarCharType()));

        assertThat(row.getRowKind()).isEqualTo(RowKind.UPDATE_AFTER);
        assertThat(row.getField(0)).isEqualTo(StringData.fromString("name"));
        assertThat(row.getField(1)).isEqualTo(7);
        assertThat(array.toObjectArray())
                .containsExactly(StringData.fromString("a"), StringData.fromString("b"));
        assertThat(map.get(StringData.fromString("one"))).isEqualTo(1);
        assertThat(entries.get(StringData.fromString("two"))).isEqualTo(2);
        assertThat(multiset.get(StringData.fromString("item"))).isEqualTo(3);
    }

    @Test
    void passesThroughInternalContainersAndUnsupportedValues() {
        GenericArrayData array = new GenericArrayData(new Object[] {StringData.fromString("a")});
        GenericMapData map = new GenericMapData(Map.of(StringData.fromString("a"), 1));
        GenericRowData row = new GenericRowData(1);

        assertThat(InternalTypeConverter.toInternal(array, new ArrayType(new VarCharType())))
                .isSameAs(array);
        assertThat(
                        InternalTypeConverter.toInternal(
                                map, new MapType(new VarCharType(), new IntType())))
                .isSameAs(map);
        assertThat(InternalTypeConverter.toInternal(row, RowType.of(new IntType()))).isSameAs(row);
        assertThat(InternalTypeConverter.toInternal("value", new BinaryType())).isEqualTo("value");
        assertThatThrownBy(
                        () ->
