package org.apache.flink.runtime.checkpoint;

import org.apache.flink.api.common.JobID;
import org.apache.flink.runtime.checkpoint.CheckpointCoordinatorTestingUtils.CheckpointCoordinatorBuilder;
import org.apache.flink.runtime.executiongraph.ExecutionAttemptID;
import org.apache.flink.runtime.executiongraph.ExecutionGraph;
import org.apache.flink.runtime.executiongraph.ExecutionVertex;
import org.apache.flink.runtime.jobgraph.JobVertexID;
import org.apache.flink.runtime.messages.checkpoint.AcknowledgeCheckpoint;
import org.apache.flink.util.concurrent.FutureUtils;
import org.apache.flink.util.concurrent.ManuallyTriggeredScheduledExecutor;

import org.junit.jupiter.api.Test;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

import static org.apache.flink.runtime.executiongraph.ExecutionGraphTestUtils.createExecutionAttemptId;
import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link CheckpointCoordinator#receiveAcknowledgeMessage}. */
class CheckpointCoordinatorReceiveAcknowledgeMessageTests {

    @Test
    void testNullMessageIsIgnored() throws Exception {
        CheckpointCoordinator coordinator = createCoordinator();
        try {
            assertThat(coordinator.receiveAcknowledgeMessage(null, "location")).isFalse();
        } finally {
            coordinator.shutdown();
        }
    }

    @Test
    void testMessageForDifferentJobIsIgnored() throws Exception {
        CheckpointContext context = createPendingCheckpoint();
        try {
            ExecutionAttemptID attemptId = currentAttemptId(context.graph);

            assertThat(
                            context.coordinator.receiveAcknowledgeMessage(
                                    new AcknowledgeCheckpoint(
                                            new JobID(), attemptId, context.checkpointId),
                                    "location"))
                    .isFalse();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isOne();
            assertThat(context.checkpoint.getNumberOfAcknowledgedTasks()).isZero();
        } finally {
            context.coordinator.shutdown();
            context.executor.shutdownNow();
        }
    }

    @Test
    void testAcknowledgementCompletesPendingCheckpoint() throws Exception {
        CheckpointContext context = createPendingCheckpoint();
        try {
            assertThat(
                            context.coordinator.receiveAcknowledgeMessage(
                                    new AcknowledgeCheckpoint(
                                            context.graph.getJobID(),
                                            currentAttemptId(context.graph),
                                            context.checkpointId),
                                    "location"))
                    .isTrue();
            assertThat(context.checkpoint.isDisposed()).isTrue();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(context.coordinator.getNumberOfRetainedSuccessfulCheckpoints()).isOne();
        } finally {
            context.coordinator.shutdown();
            context.executor.shutdownNow();
        }
    }

    @Test
    void testAcknowledgementForUnknownCheckpointReturnsFalse() throws Exception {
        CheckpointContext context = createPendingCheckpoint();
        try {
            assertThat(
                            context.coordinator.receiveAcknowledgeMessage(
                                    new AcknowledgeCheckpoint(
                                            context.graph.getJobID(),
                                            currentAttemptId(context.graph),
                                            context.checkpointId + 1),
                                    "location"))
                    .isFalse();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isOne();
            assertThat(context.checkpoint.getNumberOfAcknowledgedTasks()).isZero();
        } finally {
            context.coordinator.shutdown();
            context.executor.shutdownNow();
        }
    }

    @Test
    void testAcknowledgementAfterShutdownReturnsFalse() throws Exception {
        CheckpointCoordinator coordinator = createCoordinator();
        coordinator.shutdown();
        assertThat(
                        coordinator.receiveAcknowledgeMessage(
                                new AcknowledgeCheckpoint(
                                        new JobID(), createExecutionAttemptId(), 1L),
                                "location"))
                .isFalse();
    }

    private static CheckpointCoordinator createCoordinator() throws Exception {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        ExecutionGraph graph =
                new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
                        .addJobVertex(new JobVertexID())
                        .build(executor);
        return new CheckpointCoordinatorBuilder()
                .setTimer(new ManuallyTriggeredScheduledExecutor())
                .build(graph);
    }

    private static CheckpointContext createPendingCheckpoint() throws Exception {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        ExecutionGraph graph =
                new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
                        .addJobVertex(new JobVertexID())
                        .build(executor);
        ManuallyTriggeredScheduledExecutor timer = new ManuallyTriggeredScheduledExecutor();
        CheckpointCoordinator coordinator =
                new CheckpointCoordinatorBuilder().setTimer(timer).build(graph);
        FutureUtils.throwIfCompletedExceptionally(coordinator.triggerCheckpoint(false));
        timer.triggerAll();
        long checkpointId = coordinator.getPendingCheckpoints().keySet().iterator().next();
        return new CheckpointContext(
                coordinator,
                graph,
                coordinator.getPendingCheckpoints().get(checkpointId),
                checkpointId,
                executor);
    }

    private static ExecutionAttemptID currentAttemptId(ExecutionGraph graph) {
        ExecutionVertex vertex = graph.getAllExecutionVertices().iterator().next();
        return vertex.getCurrentExecutionAttempt().getAttemptId();
    }

    private static final class CheckpointContext {
        private final CheckpointCoordinator coordinator;
        private final ExecutionGraph graph;
        private final PendingCheckpoint checkpoint;
        private final long checkpointId;
        private final ScheduledExecutorService executor;

        private CheckpointContext(
                CheckpointCoordinator coordinator,
                ExecutionGraph graph,
                PendingCheckpoint checkpoint,
                long checkpointId,
                ScheduledExecutorService executor) {
            this.coordinator = coordinator;
            this.graph = graph;
            this.checkpoint = checkpoint;
            this.checkpointId = checkpointId;
            this.executor = executor;
        }
    }
}

