    @Test
    void deserializeRejectsUnknownHandleType() {
        assertThatThrownBy(() -> deserializeType(99))
                .isInstanceOf(IllegalStateException.class)
                .hasMessage("Reading invalid KeyedStateHandle, type: 99");
    }

    private static KeyedStateHandle deserialize(KeyedStateHandle stateHandle) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DataOutputStream output = new DataOutputStream(bytes)) {
            MetadataV2V3SerializerBase.serializeKeyedStateHandle(
                    stateHandle,
                    output,
                    MetadataV2V3SerializerBase.SerializationContext.withoutExclusiveDir());
        }
        try (DataInputStream input =
                new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return MetadataV2V3SerializerBase.deserializeKeyedStateHandle(input, null);
        }
    }

    private static KeyedStateHandle deserializeType(int type) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DataOutputStream output = new DataOutputStream(bytes)) {
            output.writeByte(type);
        }
        try (DataInputStream input =
                new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return MetadataV2V3SerializerBase.deserializeKeyedStateHandle(input, null);
        }
    }
