                new ConnectionUtils.LeaderConnectingAddressListener(rpcSystemUtils);
        listener.notifyLeaderAddress("invalid-url", UUID.randomUUID());

        assertThatThrownBy(() -> listener.findConnectingAddress(Duration.ofSeconds(1)))
