                case HYBRIDHASH_BUILD_FIRST:
                    this.joinIterator =
                            new NonReusingBuildFirstHashJoinIterator<>(
                                    in1,
                                    in2,
                                    serializer1,
                                    comparator1,
                                    serializer2,
                                    comparator2,
