package org.apache.flink.runtime.operators.hash;

import org.apache.flink.api.common.typeutils.base.IntComparator;
import org.apache.flink.api.common.typeutils.base.IntSerializer;
import org.apache.flink.core.memory.MemorySegmentFactory;
import org.apache.flink.util.MutableObjectIterator;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

class CompactingHashTableResizeHashTableTests {

    private static final int NUM_MEMORY_SEGMENTS = 128;
    private static final int MEMORY_SEGMENT_SIZE = 32 * 1024;

    @Test
    void resizeHashTableDoublesCapacityAndPreservesEntries() throws IOException {
        CompactingHashTable<Integer> hashTable = createHashTable();
        try {
            hashTable.open();
            for (int value = 0; value < 1000; value++) {
                hashTable.insertOrReplaceRecord(value);
            }

            assertThat(hashTable.resizeHashTable()).isTrue();

            Set<Integer> entries = readEntries(hashTable.getEntryIterator());
            assertThat(entries).hasSize(1000).containsExactlyInAnyOrderElementsOf(range(1000));

            hashTable.insertOrReplaceRecord(1000);
            assertThat(readEntries(hashTable.getEntryIterator())).contains(1000);
        } finally {
            hashTable.close();
        }
    }

    private static CompactingHashTable<Integer> createHashTable() {
        List<org.apache.flink.core.memory.MemorySegment> memorySegments = new ArrayList<>();
        for (int i = 0; i < NUM_MEMORY_SEGMENTS; i++) {
            memorySegments.add(MemorySegmentFactory.allocateUnpooledSegment(MEMORY_SEGMENT_SIZE));
        }
        return new CompactingHashTable<>(
                IntSerializer.INSTANCE, new IntComparator(true), memorySegments);
    }

    private static Set<Integer> readEntries(MutableObjectIterator<Integer> iterator)
            throws IOException {
        Set<Integer> entries = new HashSet<>();
        Integer value;
        while ((value = iterator.next()) != null) {
            entries.add(value);
        }
        return entries;
    }

    private static Set<Integer> range(int size) {
        Set<Integer> values = new HashSet<>();
        for (int value = 0; value < size; value++) {
            values.add(value);
        }
        return values;
    }
}

