package org.apache.flink.runtime.operators.hash;

import org.apache.flink.api.common.typeutils.TypePairComparator;
import org.apache.flink.api.common.typeutils.base.IntComparator;
import org.apache.flink.api.common.typeutils.base.IntSerializer;
import org.apache.flink.core.memory.MemorySegment;
import org.apache.flink.core.memory.MemorySegmentFactory;
import org.apache.flink.runtime.io.disk.iomanager.IOManagerAsync;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class MutableHashTableBuildTableFromSpilledPartitionTests {

    private static final int SEGMENT_SIZE = 32 * 1024;

    @Test
    void buildsInMemoryTableFromSpilledPartition() throws Exception {
        try (IOManagerAsync ioManager = new IOManagerAsync()) {
            TestHashTable table = createTable(ioManager, 40);
            HashPartition<Integer, Integer> partition =
                    createSpilledPartition(table, ioManager, 1, 2);

            table.buildTableFromSpilledPartition(partition);

            assertThat(table.partitionsBeingBuilt).hasSize(1);
            HashPartition<Integer, Integer> rebuilt = table.partitionsBeingBuilt.get(0);
            assertThat(rebuilt.getRecursionLevel()).isEqualTo(2);
            assertThat(rebuilt.isInMemory()).isTrue();
            assertThat(table.numBuckets).isEqualTo(1001);
            assertThat(readPartition(rebuilt)).hasSize(9000).contains(0, 8999);
            table.close();
        }
    }

    @Test
    void rejectsPartitionBeyondMaximumRecursionDepth() throws Exception {
        try (IOManagerAsync ioManager = new IOManagerAsync()) {
            TestHashTable table = createTable(ioManager, 40);
            HashPartition<Integer, Integer> partition =
                    createSpilledPartition(table, ioManager, 3, 1);

            assertThatThrownBy(() -> table.buildTableFromSpilledPartition(partition))
                    .isInstanceOf(RuntimeException.class)
                    .hasMessageContaining("exceeded maximum number of recursions");
            table.close();
        }
    }

    private static TestHashTable createTable(IOManagerAsync ioManager, int numSegments) {
        List<MemorySegment> memory = new ArrayList<>();
        for (int i = 0; i < numSegments; i++) {
            memory.add(MemorySegmentFactory.allocateUnpooledSegment(SEGMENT_SIZE));
        }
        TestHashTable table = new TestHashTable(memory, ioManager);
        table.writeBehindBuffers.add(
                table.availableMemory.remove(table.availableMemory.size() - 1));
        table.writeBehindBuffersAvailable = 1;
        return table;
    }

    private static HashPartition<Integer, Integer> createSpilledPartition(
            TestHashTable table, IOManagerAsync ioManager, int recursionLevel, int partitionNumber)
            throws IOException {
        HashPartition<Integer, Integer> partition =
                new HashPartition<>(
                        IntSerializer.INSTANCE,
                        IntSerializer.INSTANCE,
                        partitionNumber,
                        recursionLevel,
                        table.availableMemory.remove(table.availableMemory.size() - 1),
                        table,
                        SEGMENT_SIZE);
        for (int value = 0; value < 9000; value++) {
            partition.insertIntoBuildBuffer(value);
        }
        partition.spillPartition(
                table.availableMemory,
                ioManager,
                ioManager.createChannel(),
                table.writeBehindBuffers);
        partition.finalizeBuildPhase(
                ioManager, ioManager.createChannelEnumerator(), table.writeBehindBuffers);
        table.writeBehindBuffersAvailable = 0;
        MemorySegment returned;
        while ((returned = table.writeBehindBuffers.poll()) != null) {
            table.availableMemory.add(returned);
        }
        return partition;
    }

    private static List<Integer> readPartition(HashPartition<Integer, Integer> partition)
            throws IOException {
        List<Integer> records = new ArrayList<>();
        HashPartition<Integer, Integer>.PartitionIterator iterator =
                partition.getPartitionIterator(new IntComparator(true));
        Integer record = IntSerializer.INSTANCE.createInstance();
        while ((record = iterator.next(record)) != null) {
            records.add(record);
        }
        return records;
    }

    private static final class TestHashTable extends MutableHashTable<Integer, Integer> {
        private TestHashTable(List<MemorySegment> memory, IOManagerAsync ioManager) {
            super(
                    IntSerializer.INSTANCE,
                    IntSerializer.INSTANCE,
                    new IntComparator(true),
                    new IntComparator(true),
                    new IntPairComparator(),
                    memory,
                    ioManager,
                    false);
        }
    }

    private static final class IntPairComparator extends TypePairComparator<Integer, Integer> {
        private Integer reference;

        @Override
        public void setReference(Integer reference) {
            this.reference = reference;
        }

        @Override
        public boolean equalToReference(Integer candidate) {
            return reference.equals(candidate);
        }

        @Override
        public int compareToReference(Integer candidate) {
            return Integer.compare(candidate, reference);
        }
    }
}

