    @Test
    void addsCounterGaugeHistogramAndMeterToJobManager() {
        MetricStore store = new MetricStore();
        QueryScopeInfo scope = new QueryScopeInfo.JobManagerQueryScopeInfo("Status");

        store.add(new MetricDump.CounterDump(scope, "counter", 42));
        store.add(new MetricDump.GaugeDump(scope, "gauge", "ready"));
        store.add(
                new MetricDump.HistogramDump(
                        scope, "histogram", 1, 9, 5.0, 5.0, 2.0, 7.0, 8.0, 8.5, 8.8, 8.9, 8.99));
        store.add(new MetricDump.MeterDump(scope, "meter", 3.5));

        MetricStore.ComponentMetricStore metrics = store.getJobManagerMetricStore();
        assertThat(metrics.getMetric("Status.counter")).isEqualTo("42");
        assertThat(metrics.getMetric("Status.gauge")).isEqualTo("ready");
        assertThat(metrics.getMetric("Status.histogram_min")).isEqualTo("1");
        assertThat(metrics.getMetric("Status.histogram_max")).isEqualTo("9");
        assertThat(metrics.getMetric("Status.histogram_mean")).isEqualTo("5.0");
        assertThat(metrics.getMetric("Status.histogram_p999")).isEqualTo("8.99");
        assertThat(metrics.getMetric("Status.meter")).isEqualTo("3.5");
    }

    @Test
    void addsTaskManagerMetricAndExtractsGarbageCollectorName() {
        MetricStore store = new MetricStore();

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo(
                                "tm-1", "Status.JVM.GarbageCollector.G1"),
                        "Count",
                        "7"));

        MetricStore.TaskManagerMetricStore metrics = store.getTaskManagerMetricStore("tm-1");
        assertThat(metrics).isNotNull();
        assertThat(metrics.getMetric("Status.JVM.GarbageCollector.G1.Count")).isEqualTo("7");
        assertThat(metrics.garbageCollectorNames).containsExactly("G1");
    }

    @Test
    void addsJobMetricUsingItsJobId() {
        MetricStore store = new MetricStore();

        store.add(
                new MetricDump.CounterDump(
                        new QueryScopeInfo.JobQueryScopeInfo("job-1", "records"), "in", 12));

        assertThat(store.getJobMetricStore("job-1").getMetric("records.in")).isEqualTo("12");
    }

    @Test
    void addsRepresentativeTaskMetricToAttemptSubtaskAndTaskStores() {
        MetricStore store = new MetricStore();

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo("job-1", "vertex-1", 2, 0, "scope"),
                        "value",
                        "x"));

        assertThat(
                        store.getJobs()
                                .getSubtaskAttemptMetricStore("job-1", "vertex-1", 2, 0)
                                .getMetric("scope.value"))
                .isEqualTo("x");
        assertThat(
                        store.getJobs()
                                .getSubtaskMetricStore("job-1", "vertex-1", 2)
                                .getMetric("scope.value"))
