                        "value",
                        "old"));

        assertThat(
                        store.getJobs()
                                .getSubtaskAttemptMetricStore("job-1", "vertex-1", 2, 0)
                                .getMetric("value"))
                .isEqualTo("old");
        assertThat(store.getJobs().getSubtaskMetricStore("job-1", "vertex-1", 2).getMetric("value"))
                .isNull();
        assertThat(store.getTaskMetricStore("job-1", "vertex-1").getMetric("2.value")).isNull();
    }

    @Test
    void addsOperatorMetricWithOperatorAndSubtaskPrefixes() {
        MetricStore store = new MetricStore();

        store.add(
                new MetricDump.CounterDump(
                        new QueryScopeInfo.OperatorQueryScopeInfo("job-1", "vertex-1", 1, 0, "Map"),
                        "records",
                        4));

        assertThat(
                        store.getJobs()
                                .getSubtaskAttemptMetricStore("job-1", "vertex-1", 1, 0)
