        assertThat(
                        store.getJobs()
                                .getSubtaskMetricStore("job-1", "vertex-1", 1)
                                .getMetric("Map.records"))
                .isEqualTo("4");
        assertThat(store.getTaskMetricStore("job-1", "vertex-1").getMetric("1.Map.records"))
                .isEqualTo("4");
    }

    @Test
    void addsJobManagerOperatorMetric() {
        MetricStore store = new MetricStore();

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.JobManagerOperatorQueryScopeInfo(
                                "job-1", "vertex-1", "Map"),
                        "latency",
                        "10"));

        assertThat(
                        store.getJobManagerOperatorMetricStore("job-1", "vertex-1")
                                .getMetric("Map.latency"))
                .isEqualTo("10");
    }

    @Test
    void ignoresMetricWithEmptyName() {
        MetricStore store = new MetricStore();

        store.add(new MetricDump.GaugeDump(new QueryScopeInfo.JobManagerQueryScopeInfo(), "", "x"));

        assertThat(store.getJobManagerMetricStore().metrics).isEmpty();
    }
