import org.apache.flink.shaded.netty4.io.netty.util.ReferenceCountUtil;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collection;

import static org.assertj.core.api.Assertions.assertThat;

class FileUploadHandlerChannelRead0Tests {

    @Test
    void forwardsNonPostRequests() {
        Path uploadDir = createTempDirectory();
        EmbeddedChannel channel = newChannel(uploadDir, routes("/upload", "/upload"));
        DefaultHttpRequest request =
                new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.GET, "/upload");

        assertThat(Boolean.valueOf(channel.writeInbound(request))).isTrue();
        assertThat((Object) channel.readInbound()).isSameAs(request);
        channel.finishAndReleaseAll();
    }

    @Test
    void forwardsNonMultipartPostRequests() {
        Path uploadDir = createTempDirectory();
        EmbeddedChannel channel = newChannel(uploadDir, routes("/upload", "/upload"));
        DefaultHttpRequest request =
                new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, "/upload");
        request.headers().set(HttpHeaderNames.CONTENT_TYPE, "application/json");

        assertThat(Boolean.valueOf(channel.writeInbound(request))).isTrue();
        assertThat((Object) channel.readInbound()).isSameAs(request);
        channel.finishAndReleaseAll();
    }

    @Test
    void acceptsMultipartRequestAndForwardsJsonAndStoresFile(@TempDir Path uploadDir)
            throws Exception {
        EmbeddedChannel channel = newChannel(uploadDir, routes("/upload", "/upload"));
        HttpPostRequestEncoder encoder = createEncoder("/upload");
        encoder.addBodyAttribute("request", "{\"name\":\"test\"}");
        Path source = Files.createTempFile("payload", ".txt");
        Files.writeString(source, "hello");
        encoder.addBodyFileUpload("payload", source.toFile(), "text/plain", false);
        HttpPostRequestEncoder multipartEncoder = encoder;

        writeEncodedRequest(channel, multipartEncoder);

        org.apache.flink.shaded.netty4.io.netty.handler.codec.http.HttpRequest forwarded =
                channel.readInbound();
        assertThat(forwarded).isNotNull();
        assertThat(forwarded.headers().get(HttpHeaderNames.CONTENT_TYPE))
                .isEqualTo(RestConstants.REST_CONTENT_TYPE);
        LastHttpContent content = channel.readInbound();
        ByteBuf body = content.content();
        assertThat(body.toString(StandardCharsets.UTF_8)).isEqualTo("{\"name\":\"test\"}");

        FileUploads uploads =
                FileUploadHandler.getMultipartFileUploads(
                        channel.pipeline().context(FileUploadHandler.class));
        Collection<java.io.File> files = uploads.getUploadedFiles();
        assertThat(files)
                .singleElement()
                .satisfies(
                        file -> {
                            assertThat(file.getName()).startsWith("payload").endsWith(".txt");
                            assertThat(Files.readString(file.toPath())).isEqualTo("hello");
                        });
        uploads.close();
        channel.finishAndReleaseAll();
    }

    @Test
    void rejectsMultipartRequestForUnknownPostRoute() throws Exception {
        Path uploadDir = createTempDirectory();
        EmbeddedChannel channel = newChannel(uploadDir, routes("/allowed", "/upload"));
        HttpPostRequestEncoder encoder = createEncoder("/upload");
        encoder.addBodyAttribute("request", "{}");

        writeEncodedRequest(channel, encoder);

        HttpResponse response = channel.readOutbound();
        assertThat(response.status()).isEqualTo(HttpResponseStatus.BAD_REQUEST);
        ReferenceCountUtil.release(channel.readInbound());
        channel.finishAndReleaseAll();
    }

    private static EmbeddedChannel newChannel(Path uploadDir, MultipartRoutes routes) {
        return new EmbeddedChannel(new FileUploadHandler(uploadDir, routes));
    }

    private static MultipartRoutes routes(String postRoute, String fileRoute) {
        return new MultipartRoutes.Builder()
                .addPostRoute(postRoute)
                .addFileUploadRoute(fileRoute)
                .build();
    }

    private static HttpPostRequestEncoder createEncoder(String uri) throws Exception {
        DefaultHttpRequest request =
                new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, uri);
        return new HttpPostRequestEncoder(new DefaultHttpDataFactory(true), request, true);
    }

    private static void writeEncodedRequest(
            EmbeddedChannel channel, HttpPostRequestEncoder encoder) {
        try {
            org.apache.flink.shaded.netty4.io.netty.handler.codec.http.HttpRequest request =
                    encoder.finalizeRequest();
            channel.writeInbound(request);
            while (true) {
                HttpContent content;
                try {
                    content = encoder.readChunk(channel.alloc());
                } catch (Exception e) {
                    throw new AssertionError(e);
                }
                if (content == null) {
                    break;
                }
                channel.writeInbound(content);
                if (content instanceof LastHttpContent) {
                    break;
                }
            }
        } catch (HttpPostRequestEncoder.ErrorDataEncoderException e) {
            throw new AssertionError(e);
        }
    }

    private static Path createTempDirectory() {
        try {
            return Files.createTempDirectory("file-upload-handler-test");
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }
}

