        view.writeInt(2);
        StringSerializer.INSTANCE.serialize("one", view);
        IntSerializer.INSTANCE.serialize(1, view);
        StringSerializer.INSTANCE.serialize("two", view);
        IntSerializer.INSTANCE.serialize(2, view);
        Map<String, OperatorStateHandle.StateMetaInfo> offsets = new HashMap<>();
