class ZooKeeperUtilsStartCuratorFrameworkTests {

    @Test
    void startsTheBuiltClientAndRegistersTheUnhandledErrorListener() {
        CuratorFrameworkFactory.Builder builder = mock(CuratorFrameworkFactory.Builder.class);
        CuratorFramework client = mock(CuratorFramework.class);
        Listenable<UnhandledErrorListener> errorListeners = mock(Listenable.class);
