        verify(client).start();
    }

    @Test
    void forwardsUnhandledErrorsToTheFatalErrorHandler() {
        CuratorFrameworkFactory.Builder builder = mock(CuratorFrameworkFactory.Builder.class);
        CuratorFramework client = mock(CuratorFramework.class);
        Listenable<UnhandledErrorListener> errorListeners = mock(Listenable.class);
        FatalErrorHandler fatalErrorHandler = mock(FatalErrorHandler.class);
        when(builder.build()).thenReturn(client);
        when(client.getUnhandledErrorListenable()).thenReturn(errorListeners);

        ZooKeeperUtils.startCuratorFramework(builder, fatalErrorHandler);

        org.mockito.ArgumentCaptor<UnhandledErrorListener> listenerCaptor =
                org.mockito.ArgumentCaptor.forClass(UnhandledErrorListener.class);
        verify(errorListeners).addListener(listenerCaptor.capture());

        Throwable failure = new IllegalStateException("curator failure");
        listenerCaptor.getValue().unhandledError("unexpected error", failure);

        verify(fatalErrorHandler).onFatalError(eq(failure));
    }
}

