import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.graph.util.JobVertexBuildContext;
import org.apache.flink.streaming.api.graph.util.OperatorChainInfo;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.assertj.core.api.Assertions.assertThat;

class StreamingJobGraphGeneratorCreateChainTests {

    @Test
    void testCreateChainRecursivelyAddsChainableOperatorsAndNotifiesVisitedNodes() {
        final StreamGraph streamGraph = createStreamGraph(false);
        final JobVertexBuildContext context = createBuildContext(streamGraph);
        final Integer sourceId = streamGraph.getSourceIDs().iterator().next();
        final OperatorChainInfo chainInfo = new OperatorChainInfo(sourceId);
        final Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
        chainEntryPoints.put(sourceId, chainInfo);
        final List<Integer> visited = new ArrayList<>();

        final List<StreamEdge> transitiveEdges =
                StreamingJobGraphGenerator.createChain(
                        sourceId,
                        1,
                        chainInfo,
                        chainEntryPoints,
                        true,
                        Runnable::run,
                        context,
                        visited::add);

        assertThat(transitiveEdges).isEmpty();
        assertThat(visited).containsExactlyInAnyOrder(sourceId, sourceId + 1, sourceId + 2);
        assertThat(chainInfo.getAllChainedNodes())
                .extracting(StreamNode::getId)
                .containsExactlyInAnyOrder(sourceId, sourceId + 1, sourceId + 2);
        assertThat(context.getJobVerticesInOrder()).containsKey(sourceId);
        assertThat(context.getChainedConfigs().get(sourceId))
                .containsKeys(sourceId + 1, sourceId + 2);
    }

    @Test
    void testCreateChainCreatesNewChainForNonChainableOutput() {
        final StreamGraph streamGraph = createStreamGraph(true);
        final JobVertexBuildContext context = createBuildContext(streamGraph);
        final Integer sourceId = streamGraph.getSourceIDs().iterator().next();
        final OperatorChainInfo chainInfo = new OperatorChainInfo(sourceId);
        final Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
        chainEntryPoints.put(sourceId, chainInfo);

        final List<StreamEdge> transitiveEdges =
                StreamingJobGraphGenerator.createChain(
                        sourceId,
                        1,
                        chainInfo,
                        chainEntryPoints,
                        true,
                        Runnable::run,
                        context,
                        null);

        assertThat(transitiveEdges).hasSize(1);
        assertThat(chainEntryPoints).containsKey(sourceId + 1);
        assertThat(context.getJobVerticesInOrder()).containsKeys(sourceId, sourceId + 1);
        assertThat(chainInfo.getAllChainedNodes())
                .extracting(StreamNode::getId)
                .containsExactly(sourceId);
    }

    @Test
    void testCreateChainReturnsEmptyWhenChainStartAlreadyHasJobVertex() {
        final StreamGraph streamGraph = createStreamGraph(false);
        final JobVertexBuildContext context = createBuildContext(streamGraph);
        final Integer sourceId = streamGraph.getSourceIDs().iterator().next();
        final OperatorChainInfo chainInfo = new OperatorChainInfo(sourceId);
        context.addJobVertex(sourceId, new JobVertex("existing"));
        final List<Integer> visited = new ArrayList<>();

        assertThat(
                        StreamingJobGraphGenerator.createChain(
                                sourceId,
                                1,
                                chainInfo,
                                new HashMap<>(),
                                true,
                                Runnable::run,
                                context,
                                visited::add))
                .isEmpty();
        assertThat(visited).isEmpty();
        assertThat(chainInfo.getAllChainedNodes()).isEmpty();
    }

    private static StreamGraph createStreamGraph(boolean startNewChain) {
        final StreamExecutionEnvironment environment =
                new StreamExecutionEnvironment(new Configuration());
        final var source = environment.fromData(1);
        final var firstMap = source.map(value -> value + 1).name("map-1");
        if (startNewChain) {
            firstMap.startNewChain().map(value -> value + 1).name("map-2");
        } else {
            firstMap.map(value -> value + 1).name("map-2");
        }
        return environment.getStreamGraph();
    }

    private static JobVertexBuildContext createBuildContext(StreamGraph streamGraph) {
        final Map<Integer, byte[]> hashes =
                new StreamGraphHasherV2().traverseStreamGraphAndGenerateHashes(streamGraph);
        final List<Map<Integer, byte[]>> legacyHashes =
                Arrays.asList(
                        new StreamGraphUserHashHasher()
                                .traverseStreamGraphAndGenerateHashes(streamGraph));
        return new JobVertexBuildContext(
                new JobGraph("test"),
                streamGraph,
                new AtomicBoolean(),
                hashes,
                legacyHashes,
                new SlotSharingGroup());
    }
}

