import org.apache.flink.api.common.typeinfo.BasicTypeInfo;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.common.typeutils.CompositeType;
import org.apache.flink.api.java.tuple.Tuple2;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link FieldAccessorFactory#getAccessor(TypeInformation, int, ExecutionConfig)}. */
class FieldAccessorFactoryGetAccessorTests {

    private static final ExecutionConfig CONFIG = new ExecutionConfig();

    @Test
    void getsAndSetsTheWholeBasicValueAtPositionZero() {
        FieldAccessor<Integer, Integer> accessor =
                FieldAccessorFactory.getAccessor(BasicTypeInfo.INT_TYPE_INFO, 0, CONFIG);

        assertThat(accessor.get(1)).isEqualTo(1);
        assertThat(accessor.set(1, 2)).isEqualTo(2);
    }

    @Test
    void rejectsNonZeroPositionOnBasicValue() {
        assertThatThrownBy(
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        BasicTypeInfo.INT_TYPE_INFO, 1, CONFIG))
                .isInstanceOf(CompositeType.InvalidFieldReferenceException.class)
                .hasMessageContaining("can only select the 0th field");
    }

    @Test
    void getsAndSetsArrayElementByPosition() {
        int[] values = {10, 20};
        FieldAccessor<int[], Integer> accessor =
                FieldAccessorFactory.getAccessor(TypeInformation.of(int[].class), 1, CONFIG);

        assertThat(accessor.get(values)).isEqualTo(20);
        assertThat(accessor.set(values, 30)).isSameAs(values);
        assertThat(values).containsExactly(10, 30);
    }

    @Test
    void getsTupleFieldByPositionAndExpression() {
        TypeInformation<Tuple2<String, Integer>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<String, Integer>>() {});
        Tuple2<String, Integer> tuple = Tuple2.of("before", 7);

        FieldAccessor<Tuple2<String, Integer>, Integer> positionalAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, 1, CONFIG);
        FieldAccessor<Tuple2<String, Integer>, String> expressionAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, "f0", CONFIG);

        assertThat(positionalAccessor.get(tuple)).isEqualTo(7);
        assertThat(expressionAccessor.get(tuple)).isEqualTo("before");
        expressionAccessor.set(tuple, "after");
        assertThat(tuple.f0).isEqualTo("after");
    }

    @Test
    void getsAndSetsPojoFieldAndNestedTupleFieldByExpression() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        TestPojo pojo = new TestPojo();
        pojo.name = "old";
        pojo.coordinates = Tuple2.of(1, 2);

        FieldAccessor<TestPojo, String> fieldAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, "name", CONFIG);
        FieldAccessor<TestPojo, Integer> nestedAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, "coordinates.f1", CONFIG);

        assertThat(fieldAccessor.get(pojo)).isEqualTo("old");
        fieldAccessor.set(pojo, "new");
        assertThat(pojo.name).isEqualTo("new");
        assertThat(nestedAccessor.get(pojo)).isEqualTo(2);
        nestedAccessor.set(pojo, 3);
        assertThat(pojo.coordinates.f1).isEqualTo(3);
    }

    @Test
    void rejectsUnsupportedTypeAndMalformedExpression() {
        assertThatThrownBy(
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        TypeInformation.of(TestPojo.class), 0, CONFIG))
                .isInstanceOf(CompositeType.InvalidFieldReferenceException.class)
                .hasMessageContaining("supported on tuples, case classes, and arrays");

        assertThatThrownBy(
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        TypeInformation.of(
                                                new TypeHint<Tuple2<String, Integer>>() {}),
                                        "missing",
                                        CONFIG))
                .isInstanceOf(CompositeType.InvalidFieldReferenceException.class)
                .hasMessageContaining("Only integer values are allowed here");
    }

    /** A public-field POJO used to exercise the field-expression accessor path. */
    public static class TestPojo {
        public String name;
        public Tuple2<Integer, Integer> coordinates;

        public TestPojo() {}
    }
}

