package org.apache.flink.table.gateway.service.application;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.table.gateway.api.session.SessionEnvironment;
import org.apache.flink.table.gateway.api.session.SessionHandle;
import org.apache.flink.table.gateway.rest.util.SqlGatewayRestAPIVersion;
import org.apache.flink.table.gateway.service.context.DefaultContext;
import org.apache.flink.table.gateway.service.context.SessionContext;
import org.apache.flink.util.concurrent.Executors;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.UUID;
import java.util.concurrent.ExecutorService;

import static org.assertj.core.api.Assertions.assertThat;

class ScriptExecutorHasNextTests {

    private SessionContext sessionContext;
    private ExecutorService operationExecutorService;

    @BeforeEach
    void setUp() {
        operationExecutorService = Executors.newDirectExecutorService();
        DefaultContext defaultContext =
                new DefaultContext(
                        (Configuration)
                                StreamExecutionEnvironment.getExecutionEnvironment(
                                                new Configuration())
                                        .getConfiguration(),
                        Collections.emptyList());
        sessionContext =
                SessionContext.create(
                        defaultContext,
                        new SessionHandle(UUID.randomUUID()),
                        SessionEnvironment.newBuilder()
                                .setSessionEndpointVersion(
                                        SqlGatewayRestAPIVersion.getDefaultVersion())
                                .build(),
                        operationExecutorService);
    }

    @AfterEach
    void tearDown() throws Exception {
        sessionContext.close();
        operationExecutorService.shutdown();
    }

    @Test
    void hasNextReturnsTrueForEachSemicolonTerminatedStatement() {
        ScriptExecutor.ResultIterator iterator =
                new ScriptExecutor(sessionContext, new Printer())
                .new ResultIterator("SHOW TABLES; SHOW FUNCTIONS;");

        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next().statement).isEqualTo("SHOW TABLES; ");
        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next().statement).isEqualTo("SHOW FUNCTIONS;");
        assertThat(iterator.hasNext()).isFalse();
    }

    @Test
    void hasNextIgnoresSemicolonsInsideQuotedLiterals() {
        ScriptExecutor.ResultIterator iterator =
                new ScriptExecutor(sessionContext, new Printer())
                .new ResultIterator("SELECT 'value;still quoted'; SELECT 1;");

        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next().statement).isEqualTo("SELECT 'value;still quoted'; ");
        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next().statement).isEqualTo("SELECT 1;");
    }

    @Test
    void hasNextReturnsTrailingStatementWithoutTerminatingSemicolon() {
        ScriptExecutor.ResultIterator iterator =
                new ScriptExecutor(sessionContext, new Printer()).new ResultIterator("SHOW TABLES");

        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next().statement).isEqualTo("SHOW TABLES");
        assertThat(iterator.hasNext()).isFalse();
    }

    @Test
    void hasNextReturnsFalseForWhitespaceOnlyScript() {
        ScriptExecutor.ResultIterator iterator =
                new ScriptExecutor(sessionContext, new Printer()).new ResultIterator(" \n\t ");

        assertThat(iterator.hasNext()).isFalse();
    }
}

