class StreamTwoInputProcessorFactoryCreateTests {

    @Test
    void createBuildsProcessorAndReusesInputCounter() {
        Counter recordsIn = mock(Counter.class);
        TaskIOMetricGroup ioMetricGroup = mock(TaskIOMetricGroup.class);

        StreamMultipleInputProcessor processor = createProcessor(ioMetricGroup, recordsIn, false);

        assertThat(processor).isNotNull();
        verify(ioMetricGroup).reuseRecordsInputCounter(recordsIn);
    }

    @Test
    void createRejectsMissingOperatorChain() {
        assertThatNullPointerException()
                .isThrownBy(
                        () ->
                                StreamTwoInputProcessorFactory.create(
                                        mock(TaskInvokable.class),
                                        inputGates(),
                                        mock(IOManager.class),
                                        mock(MemoryManager.class),
                                        mock(TaskIOMetricGroup.class),
                                        mock(TwoInputStreamOperator.class),
                                        mock(WatermarkGauge.class),
                                        mock(WatermarkGauge.class),
                                        null,
                                        streamConfig(false),
                                        new Configuration(),
                                        new Configuration(),
                                        new ExecutionConfig(),
                                        getClass().getClassLoader(),
                                        mock(Counter.class),
                                        InflightDataRescalingDescriptor.NO_RESCALE,
                                        mock(Function.class),
                                        mock(TaskInfo.class),
                                        mock(CanEmitBatchOfRecordsChecker.class)));
    }

    @Test
    void createRejectsInputSelectableWhenAnInputRequiresSorting() {
        assertThatIllegalStateException()
                .isThrownBy(
                        () ->
                                createProcessor(
                                        mock(TaskIOMetricGroup.class), mock(Counter.class), true))
                .withMessage("The InputSelectable interface is not supported with sorting inputs");
    }

    private static StreamMultipleInputProcessor createProcessor(
            TaskIOMetricGroup ioMetricGroup, Counter recordsIn, boolean sorted) {
        TwoInputStreamOperator<String, String, String> operator =
                mock(TwoInputStreamOperator.class);
        if (sorted) {
            operator =
                    mock(
                            TwoInputStreamOperator.class,
                            org.mockito.Mockito.withSettings()
                                    .extraInterfaces(InputSelectable.class));
        }

        return StreamTwoInputProcessorFactory.create(
                mock(TaskInvokable.class),
                inputGates(),
                mock(IOManager.class),
                mock(MemoryManager.class),
                ioMetricGroup,
                operator,
                mock(WatermarkGauge.class),
                mock(WatermarkGauge.class),
                mock(OperatorChain.class),
                streamConfig(sorted),
                new Configuration(),
                new Configuration(),
                new ExecutionConfig(),
                StreamTwoInputProcessorFactoryCreateTests.class.getClassLoader(),
                recordsIn,
                InflightDataRescalingDescriptor.NO_RESCALE,
                mock(Function.class),
                mock(TaskInfo.class),
                mock(CanEmitBatchOfRecordsChecker.class));
    }

    private static CheckpointedInputGate[] inputGates() {
        return new CheckpointedInputGate[] {
            mock(CheckpointedInputGate.class), mock(CheckpointedInputGate.class)
        };
    }

    private static StreamConfig streamConfig(boolean sorted) {
        StreamConfig config = new StreamConfig(new Configuration());
        StreamConfig.InputRequirement requirement =
                sorted
                        ? StreamConfig.InputRequirement.SORTED
                        : StreamConfig.InputRequirement.PASS_THROUGH;
        config.setInputs(
                new StreamConfig.NetworkInputConfig(StringSerializer.INSTANCE, 0, requirement),
                new StreamConfig.NetworkInputConfig(StringSerializer.INSTANCE, 1, requirement));
        if (sorted) {
            config.setStatePartitioner(0, (String value) -> value);
            config.setStatePartitioner(1, (String value) -> value);
            config.setStateKeySerializer(StringSerializer.INSTANCE);
        }
        config.serializeAllConfigs();
        return config;
    }
}

