import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ResultFetcherFetchResultsTests {

    private static final ResolvedSchema RESULT_SCHEMA =
            ResolvedSchema.of(Column.physical("value", DataTypes.INT().notNull()));

    @Test
    void fetchNextReturnsPayloadsInBatchesAndThenEndOfStream() {
        RowData first = GenericRowData.of(1);
        RowData second = GenericRowData.of(2);
        RowData third = GenericRowData.of(3);
        ResultFetcher fetcher = fromRows(first, second, third);

        ResultSet firstResult = fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 2);
        ResultSet secondResult = fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 2);
        ResultSet endOfStream = fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 2);

        assertThat(firstResult.getResultType()).isEqualTo(ResultSet.ResultType.PAYLOAD);
        assertThat(firstResult.getNextToken()).isEqualTo(1L);
        assertThat(firstResult.getData()).containsExactly(first, second);
        assertThat(secondResult.getNextToken()).isEqualTo(2L);
        assertThat(secondResult.getData()).containsExactly(third);
        assertThat(endOfStream.getResultType()).isEqualTo(ResultSet.ResultType.EOS);
        assertThat(endOfStream.getNextToken()).isNull();
        assertThat(endOfStream.getData()).isEmpty();
    }

    @Test
    void fetchPriorReturnsPreviousPayloadWithoutAdvancingToken() {
        RowData first = GenericRowData.of(1);
        RowData second = GenericRowData.of(2);
        ResultFetcher fetcher = fromRows(first, second);

        ResultSet next = fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 2);
        ResultSet prior = fetcher.fetchResults(FetchOrientation.FETCH_PRIOR, 2);

        assertThat(next.getNextToken()).isEqualTo(1L);
        assertThat(prior.getResultType()).isEqualTo(ResultSet.ResultType.PAYLOAD);
        assertThat(prior.getNextToken()).isEqualTo(1L);
        assertThat(prior.getData()).containsExactly(first, second);
    }

    @Test
    void fetchPriorRejectsASmallerFetchSizeThanPreviousPayload() {
        ResultFetcher fetcher = fromRows(GenericRowData.of(1), GenericRowData.of(2));
        fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 2);

        assertThatThrownBy(() -> fetcher.fetchResults(FetchOrientation.FETCH_PRIOR, 1))
                .isInstanceOf(SqlExecutionException.class)
                .hasMessageContaining("must be not less than the previous returned buffer size");
    }

    @Test
    void fetchWithInvalidSizeFailsBeforeReadingResults() {
        ResultFetcher fetcher = fromRows(GenericRowData.of(1));

        assertThatThrownBy(() -> fetcher.fetchResults(FetchOrientation.FETCH_NEXT, 0))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage("The max rows should be larger than 0.");
    }

    @Test
    void fetchWithUnexpectedTokenIsRejected() {
        ResultFetcher fetcher = fromRows(GenericRowData.of(1));

        assertThatThrownBy(() -> fetcher.fetchResults(1L, 1))
                .isInstanceOf(SqlExecutionException.class)
                .hasMessage("Expecting token to be 0, but found 1.");
    }

    private static ResultFetcher fromRows(RowData... rows) {
        List<RowData> results = Arrays.asList(rows);
        return new ResultFetcher(
                OperationHandle.create(),
                RESULT_SCHEMA,
                CloseableIterator.adapterForIterator(results.iterator()),
                StaticResultProvider.SIMPLE_ROW_DATA_TO_STRING_CONVERTER,
                true,
                null,
                ResultKind.SUCCESS_WITH_CONTENT,
                10,
                TableResultUtils.buildPrintStyle(
                        RESULT_SCHEMA, StaticResultProvider.SIMPLE_ROW_DATA_TO_STRING_CONVERTER));
    }
}

