/** Tests for {@link SqlValidatorImpl#performUnconditionalRewrites(SqlNode, boolean)}. */
class SqlValidatorImplPerformUnconditionalRewritesTests {

    private final TestValidator validator = new TestValidator();

    @Test
    void nullNodeIsPreservedAsNull() {
        assertThat(validator.rewrite(null, false)).isNull();
    }

    @Test
    void valuesClauseIsNotWrappedOrChanged() throws Exception {
        SqlNode values = SqlParser.create("VALUES (1), (2)").parseQuery();

        SqlNode rewritten = validator.rewrite(values, false);

        assertThat(rewritten).isSameAs(values);
        assertThat(rewritten.getKind()).isEqualTo(SqlKind.VALUES);
    }

    @Test
    void explicitTableIsRewrittenToSelectStar() throws Exception {
        SqlNode table = SqlParser.create("TABLE orders").parseQuery();

        SqlNode rewritten = validator.rewrite(table, false);

        assertThat(rewritten).isInstanceOf(SqlSelect.class);
        SqlSelect select = (SqlSelect) rewritten;
        assertThat(select.getSelectList()).hasSize(1);
        assertThat(select.getSelectList().get(0).toString()).isEqualTo("*");
        assertThat(select.getFrom().toString()).isEqualTo("ORDERS");
    }

    @Test
    void orderByIsPushedIntoSelectWhenSelectHasNoOrderBy() throws Exception {
        SqlNode orderBy =
                SqlParser.create("SELECT a FROM t ORDER BY a OFFSET 2 ROWS FETCH NEXT 3 ROWS ONLY")
                        .parseQuery();

        SqlNode rewritten = validator.rewrite(orderBy, false);

        assertThat(rewritten).isInstanceOf(SqlSelect.class);
        SqlSelect select = (SqlSelect) rewritten;
        assertThat(select.getOrderList()).hasSize(1);
        assertThat(select.getOrderList().get(0).toString()).isEqualTo("A");
        assertThat(select.getOffset().toString()).isEqualTo("2");
        assertThat(select.getFetch().toString()).isEqualTo("3");
        assertThat(select.getFrom().toString()).isEqualTo("T");
    }

    @Test
    void existingSelectOrderByIsNotClobbered() throws Exception {
        SqlSelect query = (SqlSelect) SqlParser.create("SELECT a FROM t ORDER BY b").parseQuery();
        SqlNode orderBy =
                new SqlOrderBy(
                        SqlParserPos.ZERO,
                        query,
                        new SqlNodeList(
                                Collections.singletonList(
                                        new SqlIdentifier("a", SqlParserPos.ZERO)),
                                SqlParserPos.ZERO),
                        null,
                        null);

        SqlNode rewritten = validator.rewrite(orderBy, false);

        assertThat(rewritten).isInstanceOf(SqlSelect.class);
        SqlSelect select = (SqlSelect) rewritten;
        assertThat(select.getOrderList()).hasSize(1);
        assertThat(select.getOrderList().get(0).toString()).isEqualTo("B");
    }

    private static final class TestValidator extends SqlValidatorImpl {
        private TestValidator() {
            super(
                    SqlStdOperatorTable.instance(),
                    new CalciteCatalogReader(
                            CalciteSchema.createRootSchema(false),
                            Collections.singletonList(""),
                            new JavaTypeFactoryImpl(),
                            CalciteConnectionConfig.DEFAULT),
                    new JavaTypeFactoryImpl(),
                    Config.DEFAULT);
        }

        private SqlNode rewrite(SqlNode node, boolean underFrom) {
            return performUnconditionalRewrites(node, underFrom);
        }
    }
}

