                .isEqualTo(new DateString("2024-01-02"));
        assertThat(timestampLiteral.getValueAs(TimestampString.class))
                .isEqualTo(new TimestampString("2024-01-02 03:04:05.678"));
    }

    @Test
    void makeLiteralCreatesArrayConstructorForArrayType() {
