    @Test
    void makeLiteralCreatesBinaryLiteralWithoutCastForVarbinary() {
        RelDataType type = typeFactory.createSqlType(VARBINARY, 2);

        RexNode literal = rexBuilder.makeLiteral(new ByteString(new byte[] {1, 2}), type);

        assertThat(literal).isInstanceOf(RexLiteral.class);
        RexLiteral rexLiteral = (RexLiteral) literal;
        assertThat(rexLiteral.getTypeName()).isEqualTo(SqlTypeName.BINARY);
        assertThat(rexLiteral.getValueAs(ByteString.class))
                .isEqualTo(new ByteString(new byte[] {1, 2}));
    }
