        final RelDecorrelator decorrelator = newDecorrelator(project, relBuilder);

        final RelDecorrelator.Frame frame = decorrelator.getInvoke(project, false, null, true);

        assertThat(frame).isNotNull();
        assertThat(frame.r).isInstanceOf(LogicalProject.class);
        assertThat(frame.r.getRowType().getFieldNames()).containsExactly("name");
        assertThat(frame.r.getInputs()).hasSize(1);
        assertThat(frame.r.getInput(0)).isNotSameAs(project.getInput(0));
        assertThat(frame.oldToNewOutputs).containsExactly(Map.entry(0, 0));
        assertThat(frame.corDefOutputs).isEmpty();
    }

    private static RelDecorrelator newDecorrelator(RelNode root, RelBuilder relBuilder) {
        return new RelDecorrelator(
                new RelDecorrelator.CorelMapBuilder().build(root),
                root.getCluster().getPlanner().getContext(),
                relBuilder);
    }

    private static RelBuilder newRelBuilder() {
        final SqlTypeFactoryImpl typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final RelOptCluster cluster =
                RelOptCluster.create(new VolcanoPlanner(), new RexBuilder(typeFactory));
        return RelFactories.LOGICAL_BUILDER.create(cluster, null);
    }
}

