        assertThatThrownBy(() -> node.translateToPlanInternal(null, null))
                .isInstanceOf(TableException.class)
                .hasMessage("The window can only be ordered by a single time column.");
    }

    @Test
    void rejectsDescendingOrder() {
        final StreamExecOverAggregate node = createNode(createGroup(false, 1));

        assertThatThrownBy(() -> node.translateToPlanInternal(null, null))
                .isInstanceOf(TableException.class)
                .hasMessage("The window can only be ordered in ASCENDING mode.");
    }

    private static StreamExecOverAggregate createNode(OverSpec.GroupSpec... groups) {
        final OverSpec overSpec =
                new OverSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Arrays.asList(groups),
