                TableConfig.getDefault(),
                overSpec,
                InputProperty.DEFAULT,
                RowType.of(new org.apache.flink.table.types.logical.LogicalType[0]),
                "test");
    }

    private static OverSpec.GroupSpec createGroup(boolean ascending, int fieldIndex) {
        return createGroup(
                SortSpec.builder().addField(fieldIndex, ascending, true).build());
    }

    private static OverSpec.GroupSpec createGroup(SortSpec sortSpec) {
        return new OverSpec.GroupSpec(
                sortSpec,
                true,
                RexWindowBounds.UNBOUNDED_PRECEDING,
                RexWindowBounds.CURRENT_ROW,
                Collections.emptyList());
    }
