/** Tests for {@link RemoveCorrelationForScalarAggregateRule#onMatch}. */
class RelDecorrelatorOnMatchTests {

    @Test
    void removesCorrelationForCountStarScalarAggregate() {
        RelBuilder builder = RelBuilder.create(frameworkConfig());
        RelNode left = builder.values(new String[] {"id"}, 1, 2).build();
        CorrelationId correlationId = new CorrelationId(0);
        RexNode correlation = builder.getRexBuilder().makeCorrel(left.getRowType(), correlationId);
        RexNode correlatedId = builder.getRexBuilder().makeFieldAccess(correlation, 0);

        builder.clear();
        RelNode right =
                builder.values(new String[] {"value"}, 1, 2, 3)
                        .filter(
                                builder.call(
                                        SqlStdOperatorTable.EQUALS,
                                        builder.field("value"),
                                        correlatedId))
                        .project(builder.field("value"))
                        .build();
        builder.clear();
        RelNode correlatedAggregate =
                builder.push(right)
                        .aggregate(builder.groupKey(), builder.countStar("count"))
                        .project(builder.field("count"))
                        .build();
        RelNode correlate =
                LogicalCorrelate.create(
                        left,
                        correlatedAggregate,
                        ImmutableList.of(),
                        correlationId,
                        ImmutableBitSet.of(0),
                        org.apache.calcite.rel.core.JoinRelType.LEFT);

        RelNode result = RelDecorrelator.decorrelateQuery(correlate);

        assertThat(result).doesNotContainInstanceOf(Correlate.class);
        assertThat(result).isInstanceOf(Project.class);
        assertThat(RelOptUtil.toString(result)).contains("LogicalAggregate");
    }

    @Test
    void leavesNonCorrelatedInputUnchanged() {
        RelBuilder builder = RelBuilder.create(frameworkConfig());
        RelNode input = builder.values(new String[] {"id"}, 1).build();

        assertThat(RelDecorrelator.decorrelateQuery(input)).isSameAs(input);
    }

    private static FrameworkConfig frameworkConfig() {
        return Frameworks.newConfigBuilder().defaultSchema(null).build();
    }
}

