    @Test
    void convertFromNullCreatesOneRowValues() {
        RelNode root = converter.convertFromForTest(null);

        assertThat(root).isInstanceOf(LogicalValues.class);
        assertThat(root.getRowType().getFieldCount()).isZero();
        assertThat(((LogicalValues) root).getTuples()).hasSize(1);
    }

    @Test
    void convertFromValuesWithFieldNamesRenamesFields() throws SqlParseException {
        SqlNode values = parse("VALUES (1, 'one')");

        RelNode root = converter.convertFromForTest(values, "number", "word");

        assertThat(root.getRowType().getFieldNames()).containsExactly("number", "word");
        assertThat(root.getRowType().getField(0).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.INTEGER);
        assertThat(root.getRowType().getField(1).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.VARCHAR);
    }

    @Test
    void convertFromAliasAddsQueryBlockAliasWhenQueryHintsArePresent() throws SqlParseException {
        SqlSelect select = (SqlSelect) parse("SELECT * FROM (VALUES (1)) AS v");
        SqlNode query = select.getFrom();
        converter.containsQueryHints();

        RelNode root = converter.convertFromForTest(query);

        assertThat(root).isInstanceOf(Hintable.class);
        List<RelHint> aliasHints =
                ((Hintable) root)
                        .getHints().stream()
                                .filter(hint -> FlinkHints.HINT_ALIAS.equals(hint.hintName))
                                .collect(Collectors.toList());
        assertThat(aliasHints)
                .singleElement()
                .satisfies(hint -> assertThat(hint.listOptions).containsExactly("v"));
    }

    @Test
    void convertFromRejectsUnsupportedSqlNodeKind() {
        SqlNode literal = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);

        assertThatThrownBy(() -> converter.convertFromForTest(literal))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("not a join operator");
    }

    private static SqlNode parse(String sql) throws SqlParseException {
        return SqlParser.create(sql).parseQuery();
    }

    private static final class TestConverter extends SqlToRelConverter {
        private TestConverter(
                SqlValidator validator,
                CalciteCatalogReader catalogReader,
                RelOptCluster cluster,
                SqlRexConvertletTable convertletTable) {
            super(
                    null,
                    validator,
                    catalogReader,
                    cluster,
                    convertletTable,
                    SqlToRelConverter.config());
        }

        private RelNode convertFromForTest(SqlNode from, String... fieldNames) {
            Blackboard bb = createBlackboard(validator.getEmptyScope(), null, false);
            convertFrom(bb, from, fieldNames.length == 0 ? null : List.of(fieldNames));
            return bb.root();
        }
    }
