/** Unit tests for {@link FlinkAggregateExpandDistinctAggregatesRule#onMatch(RelOptRuleCall)}. */
class FlinkAggregateExpandDistinctAggregatesRuleOnMatchTests {

    @Test
    void onMatchDoesNothingWhenAggregateHasNoAccurateDistinctCall() {
        AggregateCall aggregateCall = aggregateCall(false, false);
        Aggregate aggregate = aggregateWith(aggregateCall);
        RelOptRuleCall ruleCall = ruleCall(aggregate);

        assertThatCode(() -> FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(ruleCall))
                .doesNotThrowAnyException();

        verify(ruleCall, never()).transformTo(org.mockito.ArgumentMatchers.any());
    }

    @Test
    void onMatchRejectsMixedAccurateAndApproximateDistinctCalls() {
        Aggregate aggregate =
                aggregateWith(aggregateCall(true, false), aggregateCall(true, true));
        RelOptRuleCall ruleCall = ruleCall(aggregate);

        assertThatThrownBy(
                        () ->
                                FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(
                                        ruleCall))
                .isInstanceOf(TableException.class)
                .hasMessageContaining("both Distinct AggCall and Approximate Distinct AggCall")
                .hasMessageContaining("Please choose one of them.");

        verify(ruleCall, never()).transformTo(org.mockito.ArgumentMatchers.any());
    }

    @Test
    void onMatchSkipsNonSimpleGroupingSets() {
        Aggregate aggregate = aggregateWith(aggregateCall(true, false));
        when(aggregate.getGroupSets())
                .thenReturn(
                        ImmutableList.of(ImmutableBitSet.of(), ImmutableBitSet.of(0)));
        RelOptRuleCall ruleCall = ruleCall(aggregate);

        assertThatCode(() -> FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(ruleCall))
                .doesNotThrowAnyException();

        verify(ruleCall, never()).transformTo(org.mockito.ArgumentMatchers.any());
    }

    private static RelOptRuleCall ruleCall(Aggregate aggregate) {
        RelOptRuleCall ruleCall = mock(RelOptRuleCall.class);
        when(ruleCall.rel(0)).thenReturn(aggregate);
        return ruleCall;
    }

    private static Aggregate aggregateWith(AggregateCall... aggregateCalls) {
        Aggregate aggregate = mock(Aggregate.class);
        when(aggregate.getAggCallList()).thenReturn(ImmutableList.copyOf(aggregateCalls));
        when(aggregate.getGroupSets()).thenReturn(ImmutableList.of(ImmutableBitSet.of()));
        return aggregate;
    }

    private static AggregateCall aggregateCall(boolean distinct, boolean approximate) {
        AggregateCall aggregateCall = mock(AggregateCall.class);
        when(aggregateCall.isDistinct()).thenReturn(distinct);
        when(aggregateCall.isApproximate()).thenReturn(approximate);
        when(aggregateCall.getArgList()).thenReturn(Collections.singletonList(0));
        return aggregateCall;
    }
