/** Tests the transformations performed by {@link FlinkAggregateJoinTransposeRule#onMatch}. */
class FlinkAggregateJoinTransposeRuleOnMatchTests extends TableTestBase {

    private BatchTableTestUtil util;

    @BeforeEach
    void setup() {
        util = batchTestUtil(TableConfig.getDefault());
        FlinkChainedProgram<BatchOptimizeContext> program = new FlinkChainedProgram<>();
        program.addLast(
                "rules",
                FlinkGroupProgramBuilder.<BatchOptimizeContext>newBuilder()
                        .addProgram(
                                FlinkHepRuleSetProgramBuilder.<BatchOptimizeContext>newBuilder()
                                        .setHepRulesExecutionType(
                                                HEP_RULES_EXECUTION_TYPE.RULE_COLLECTION())
                                        .setHepMatchOrder(HepMatchOrder.BOTTOM_UP)
                                        .add(RuleSets.ofList(AggregateReduceGroupingRule.INSTANCE))
                                        .build(),
                                "reduce useless grouping")
                        .addProgram(
                                FlinkHepRuleSetProgramBuilder.<BatchOptimizeContext>newBuilder()
                                        .setHepRulesExecutionType(
                                                HEP_RULES_EXECUTION_TYPE.RULE_COLLECTION())
                                        .setHepMatchOrder(HepMatchOrder.BOTTOM_UP)
                                        .add(
                                                RuleSets.ofList(
                                                        AggregateReduceGroupingRule.INSTANCE,
                                                        CoreRules.FILTER_INTO_JOIN,
                                                        CoreRules.JOIN_CONDITION_PUSH,
                                                        CoreRules.FILTER_AGGREGATE_TRANSPOSE,
                                                        CoreRules.FILTER_PROJECT_TRANSPOSE,
                                                        CoreRules.FILTER_MERGE,
                                                        CoreRules.AGGREGATE_PROJECT_MERGE,
                                                        FlinkAggregateJoinTransposeRule.EXTENDED))
                                        .build(),
                                "aggregate join transpose")
                        .build());
        util.replaceBatchProgram(program);

        util.addTableSource(
                "T",
                Schema.newBuilder()
                        .column("a", DataTypes.INT())
                        .column("b", DataTypes.INT())
                        .column("c", DataTypes.STRING())
                        .build());
        util.tableEnv()
                .executeSql(
                        "CREATE TABLE T2 ("
                                + " a2 INT,"
                                + " b2 INT PRIMARY KEY NOT ENFORCED,"
                                + " c2 STRING"
                                + ") WITH ("
                                + " 'connector' = 'values',"
                                + " 'bounded' = 'true',"
                                + " 'enable-projection-push-down' = 'false')");
    }

    @Test
    void testPushCountAggThroughJoinOverUniqueColumn() {
        util.verifyRelPlan(
                "SELECT COUNT(A.a) FROM (SELECT DISTINCT a FROM T) AS A JOIN T AS B ON A.a=B.a");
    }

    @Test
    void testPushSumAggThroughJoinOverUniqueColumn() {
        util.verifyRelPlan(
                "SELECT SUM(A.a) FROM (SELECT DISTINCT a FROM T) AS A JOIN T AS B ON A.a=B.a");
    }

    @Test
    void testPushAggThroughJoinWithUniqueJoinKey() {
        util.verifyRelPlan(
                "WITH T1 AS (SELECT a AS a1, COUNT(b) AS b1 FROM T GROUP BY a),"
                        + " T2 AS (SELECT COUNT(a) AS a2, b AS b2 FROM T GROUP BY b)"
                        + " SELECT MIN(a1), MIN(b1), MIN(a2), MIN(b2), a, b, COUNT(c)"
                        + " FROM (SELECT * FROM T1, T2, T WHERE a1 = b2 AND a1 = a) t"
                        + " GROUP BY a, b");
    }

    @Test
    void testSomeAggCallColumnsAndJoinConditionColumnsAreSame() {
        util.verifyRelPlan(
                "SELECT MIN(a2), MIN(b2), a, b, COUNT(c2) FROM "
                        + "(SELECT * FROM T2, T WHERE b2 = b) t GROUP BY b, a");
    }

    @Test
    void testAggregateWithAuxGroupWhenJoinKeyIsUnique() {
        util.verifyRelPlan(
                "SELECT a2, b2, c2, SUM(a) FROM "
                        + "(SELECT * FROM T2, T WHERE b2 = b) GROUP BY a2, b2, c2");
    }

    @Test
    void testAggregateWithAuxGroupWhenJoinKeyIsNotUnique() {
        util.verifyRelPlan(
                "SELECT a2, b2, c2, SUM(a) FROM "
                        + "(SELECT * FROM T2, T WHERE a2 = a) GROUP BY a2, b2, c2");
    }
}

