import org.apache.flink.table.api.config.OptimizerConfigOptions;
import org.apache.flink.table.planner.utils.TableTestBase;
import org.apache.flink.table.planner.utils.TableTestUtil;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for the relational expression produced by {@link SplitAggregateRule#onMatch}. */
class SplitAggregateRuleOnMatchTests extends TableTestBase {

    private TableTestUtil util;

    @BeforeEach
    void setUp() {
        TableConfig tableConfig = TableConfig.getDefault();
        tableConfig.set(OptimizerConfigOptions.TABLE_OPTIMIZER_DISTINCT_AGG_SPLIT_ENABLED, true);
        util = streamTestUtil(tableConfig);
        util.addTableSource(
                "MyTable",
                new org.apache.flink.api.common.typeinfo.TypeInformation<?>[] {
                    org.apache.flink.api.common.typeinfo.BasicTypeInfo.LONG_TYPE_INFO,
                    org.apache.flink.api.common.typeinfo.BasicTypeInfo.INT_TYPE_INFO,
                    org.apache.flink.api.common.typeinfo.BasicTypeInfo.STRING_TYPE_INFO
                },
                new String[] {"a", "b", "c"});
        util.buildStreamProgram("physical");
    }

    @Test
    void onMatchSplitsDistinctAggregateIntoPartialAndFinalAggregates() {
        String plan = util.tableEnv().explainSql("SELECT COUNT(DISTINCT c) FROM MyTable");

        assertThat(plan)
                .contains("FlinkLogicalAggregate(group=[{}], agg#0=[$SUM0($1)]")
                .contains("FlinkLogicalAggregate(group=[{1}], agg#0=[COUNT(DISTINCT $0)]")
                .contains("MOD(HASH_CODE(c), 1024)");
    }

    @Test
    void onMatchPreservesGroupKeysAndSplitsMultipleDistinctAggregates() {
        String plan =
                util.tableEnv()
                        .explainSql(
                                "SELECT a, COUNT(DISTINCT b), SUM(DISTINCT c) FROM MyTable GROUP BY a");

        assertThat(plan)
                .contains("FlinkLogicalAggregate(group=[{0}]")
                .contains("COUNT(DISTINCT")
                .contains("SUM(DISTINCT")
                .contains("FlinkLogicalExpand");
    }
}

