/** Unit tests for {@link FlinkSemiAntiJoinJoinTransposeRule#onMatch(RelOptRuleCall)}. */
class FlinkSemiAntiJoinJoinTransposeRuleOnMatchTests {

    @Test
    void testOnMatchTransposesSemiJoinUsingJoinLeftInput() {
        TestRelBuilder builder = new TestRelBuilder();
        RelNode x = builder.values(1);
        RelNode y = builder.values(1);
        RelNode z = builder.values(1);
        LogicalJoin join = builder.join(x, y, JoinRelType.INNER, builder.equalsRef(0, 1));
        LogicalJoin semiJoin =
                builder.join(
                        join,
                        z,
                        JoinRelType.SEMI,
                        builder.equalsRef(0, join.getRowType().getFieldCount()));

        RelOptRuleCall call = callFor(semiJoin, join);
        FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.onMatch(call);

        verify(call).transformTo(org.mockito.ArgumentMatchers.argThat(this::containsLeftSemiJoin));
    }

    @Test
    void testOnMatchTransposesAntiJoinUsingJoinRightInput() {
        TestRelBuilder builder = new TestRelBuilder();
        RelNode x = builder.values(1);
        RelNode y = builder.values(1);
        RelNode z = builder.values(1);
        LogicalJoin join = builder.join(x, y, JoinRelType.INNER, builder.equalsRef(0, 1));
        LogicalJoin antiJoin =
                builder.join(
                        join,
                        z,
                        JoinRelType.ANTI,
                        builder.equalsRef(1, join.getRowType().getFieldCount()));

        RelOptRuleCall call = callFor(antiJoin, join);
        FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.onMatch(call);

        verify(call).transformTo(org.mockito.ArgumentMatchers.argThat(this::containsRightAntiJoin));
    }

    @Test
    void testOnMatchDoesNotTransformUnsupportedJoinConditions() {
        TestRelBuilder builder = new TestRelBuilder();
        RelNode x = builder.values(1);
        RelNode y = builder.values(1);
        RelNode z = builder.values(1);
        LogicalJoin join = builder.join(x, y, JoinRelType.LEFT, builder.equalsRef(0, 1));
        LogicalJoin semiJoin =
                builder.join(
                        join,
                        z,
                        JoinRelType.SEMI,
                        builder.equalsRef(0, join.getRowType().getFieldCount()));

        RelOptRuleCall call = callFor(semiJoin, join);
        FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.onMatch(call);

        verify(call, never()).transformTo(org.mockito.ArgumentMatchers.any());
    }

    private RelOptRuleCall callFor(LogicalJoin topJoin, LogicalJoin childJoin) {
        RelOptRuleCall call = mock(RelOptRuleCall.class);
        when(call.rel(0)).thenReturn(topJoin);
        when(call.rel(1)).thenReturn(childJoin);
        return call;
    }

    private boolean containsLeftSemiJoin(RelNode node) {
        LogicalJoin join = (LogicalJoin) node;
        return join.getLeft() instanceof LogicalJoin
                && ((LogicalJoin) join.getLeft()).getJoinType() == JoinRelType.SEMI;
    }

    private boolean containsRightAntiJoin(RelNode node) {
        LogicalJoin join = (LogicalJoin) node;
        return join.getRight() instanceof LogicalJoin
                && ((LogicalJoin) join.getRight()).getJoinType() == JoinRelType.ANTI;
    }

    private static final class TestRelBuilder {
        private final RelOptCluster cluster;
        private final RelDataTypeFactory typeFactory;
        private final RexBuilder rexBuilder;

        private TestRelBuilder() {
            HepPlanner planner = new HepPlanner(FlinkSemiAntiJoinJoinTransposeRule.INSTANCE);
            this.typeFactory = new org.apache.calcite.jdbc.JavaTypeFactoryImpl();
            this.rexBuilder = new RexBuilder(typeFactory);
            this.cluster = RelOptCluster.create(planner, rexBuilder);
        }

        private RelNode values(int fieldCount) {
            RelDataTypeFactory.Builder typeBuilder = typeFactory.builder();
            for (int i = 0; i < fieldCount; i++) {
                typeBuilder.add("f" + i, typeFactory.createJavaType(Integer.class));
            }
            RelDataType rowType = typeBuilder.build();
            return LogicalValues.create(cluster, rowType, ImmutableList.of());
        }

        private RexNode equalsRef(int leftIndex, int rightIndex) {
            return rexBuilder.makeCall(
                    SqlStdOperatorTable.EQUALS,
                    rexBuilder.makeInputRef(typeFactory.createJavaType(Integer.class), leftIndex),
                    rexBuilder.makeInputRef(typeFactory.createJavaType(Integer.class), rightIndex));
        }

        private LogicalJoin join(
                RelNode left, RelNode right, JoinRelType joinType, RexNode condition) {
            return LogicalJoin.create(
                    left, right, ImmutableList.of(), condition, ImmutableBitSet.of(), joinType);
        }
    }
