import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link SubQueryDecorrelator.SubQueryRelDecorrelator#decorrelateRel}. */
class SubQueryDecorrelatorDecorrelateRelTests {

    @Test
    void decorrelateRelValuesPreservesNodeAndCreatesIdentityMapping() throws Exception {
        RelOptCluster cluster = newCluster();
        LogicalValues values = twoColumnValues(cluster);
        SubQueryDecorrelator.SubQueryRelDecorrelator decorrelator = newDecorrelator(cluster);

        Object frame = decorrelator.decorrelateRel(values);

        assertThat(frameField(frame, "r")).isSameAs(values);
        assertThat(frameField(frame, "c")).isNull();
        assertThat(frameField(frame, "oldToNewOutputs")).containsEntry(0, 0).containsEntry(1, 1);
    }

    @Test
    void decorrelateRelDispatchesValuesThroughReflectiveVisitor() throws Exception {
        RelOptCluster cluster = newCluster();
        LogicalValues values = twoColumnValues(cluster);
        SubQueryDecorrelator.SubQueryRelDecorrelator decorrelator = newDecorrelator(cluster);

        Object frame = decorrelator.getInvoke(values);

        assertThat(frameField(frame, "r")).isSameAs(values);
        assertThat(frameField(frame, "oldToNewOutputs")).hasSize(values.getRowType().getFieldCount());
    }

    private static SubQueryDecorrelator.SubQueryRelDecorrelator newDecorrelator(
            RelOptCluster cluster) {
        RelBuilder relBuilder = org.apache.flink.table.planner.calcite.FlinkRelBuilder.of(cluster, null);
        return new SubQueryDecorrelator.SubQueryRelDecorrelator(
                null, relBuilder, cluster.getRexBuilder());
    }

    private static LogicalValues twoColumnValues(RelOptCluster cluster) {
        RelDataTypeFactory typeFactory = cluster.getTypeFactory();
        RelDataType rowType =
                typeFactory.builder()
                        .add("left", typeFactory.createSqlType(org.apache.calcite.sql.SqlTypeName.INTEGER))
                        .add("right", typeFactory.createSqlType(org.apache.calcite.sql.SqlTypeName.INTEGER))
                        .build();
        return LogicalValues.create(
                cluster,
                rowType,
                Collections.singletonList(
                        Arrays.asList(
                                cluster.getRexBuilder().makeExactLiteral(java.math.BigDecimal.ONE),
                                cluster.getRexBuilder().makeExactLiteral(java.math.BigDecimal.TWO))));
    }

    private static RelOptCluster newCluster() {
        RelDataTypeFactory typeFactory =
                new org.apache.calcite.jdbc.JavaTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        return RelOptCluster.create(
                new HepPlanner(new HepProgramBuilder().build()), new RexBuilder(typeFactory));
    }

    private static Object frameField(Object frame, String name) throws Exception {
        Field field = frame.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(frame);
    }
}

