            new FlinkTypeFactory(getClass().getClassLoader(), FlinkTypeSystem.INSTANCE);

    @Test
    void convertsScalarTypesAndPreservesNullabilityAndAttributes() {
        final RelDataType decimal =
                LogicalRelDataTypeConverter.toRelDataType(
                        new DecimalType(false, 12, 3), typeFactory);
        final RelDataType varchar =
                LogicalRelDataTypeConverter.toRelDataType(new VarCharType(false, 17), typeFactory);

        assertThat(decimal.getSqlTypeName()).isEqualTo(SqlTypeName.DECIMAL);
        assertThat(decimal.getPrecision()).isEqualTo(12);
        assertThat(decimal.getScale()).isEqualTo(3);
        assertThat(decimal.isNullable()).isFalse();
        assertThat(varchar.getSqlTypeName()).isEqualTo(SqlTypeName.VARCHAR);
        assertThat(varchar.getPrecision()).isEqualTo(17);
        assertThat(varchar.isNullable()).isFalse();
    }

    @Test
    void convertsNestedCollectionAndRowTypes() {
        final RowType logicalType =
                RowType.of(
                        new ArrayType(new IntType(false)),
                        new MapType(new VarCharType(false, 8), new DecimalType(10, 2)),
                        new VarCharType(false, 4));

        final RelDataType result =
                LogicalRelDataTypeConverter.toRelDataType(logicalType, typeFactory);

        assertThat(result.getSqlTypeName()).isEqualTo(SqlTypeName.ROW);
        assertThat(result.getFieldNames()).containsExactly("f0", "f1", "f2");
        assertThat(result.getFieldList().get(0).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.ARRAY);
        assertThat(result.getFieldList().get(0).getType().getComponentType().isNullable())
                .isFalse();
        assertThat(result.getFieldList().get(1).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.MAP);
        assertThat(result.getFieldList().get(2).getType().getPrecision()).isEqualTo(4);
    }

    @Test
    void convertsTimeIndicatorTypes() {
        final RelDataType rowtime =
                LogicalRelDataTypeConverter.toRelDataType(
                        new TimestampType(false, TimestampKind.ROWTIME, 3), typeFactory);
        final RelDataType proctime =
                LogicalRelDataTypeConverter.toRelDataType(
                        new LocalZonedTimestampType(false, TimestampKind.PROCTIME, 3), typeFactory);

        assertThat(rowtime.getSqlTypeName()).isEqualTo(SqlTypeName.TIMESTAMP);
        assertThat(rowtime.isNullable()).isFalse();
        assertThat(rowtime.toString()).contains("ROWTIME");
        assertThat(proctime.getSqlTypeName()).isEqualTo(SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE);
        assertThat(proctime.toString()).contains("PROCTIME");
    }

    @Test
    void convertsIntervalAndSpecialSqlTypes() {
        final RelDataType interval =
                LogicalRelDataTypeConverter.toRelDataType(
                        new org.apache.flink.table.types.logical.DayTimeIntervalType(
                                org.apache.flink.table.types.logical.DayTimeIntervalType
                                        .DayTimeResolution.DAY_TO_SECOND,
                                3,
                                6),
                        typeFactory);
        final RelDataType nullType =
                LogicalRelDataTypeConverter.toRelDataType(
                        new org.apache.flink.table.types.logical.NullType(), typeFactory);

        assertThat(interval.getSqlTypeName()).isEqualTo(SqlTypeName.INTERVAL_DAY_TIME);
        assertThat(interval.getIntervalQualifier().toString()).contains("DAY");
        assertThat(nullType.getSqlTypeName()).isEqualTo(SqlTypeName.NULL);
    }

    @Test
    void rejectsUnsupportedZonedAndDistinctTypes() {
        assertThatThrownBy(
                        () ->
                                LogicalRelDataTypeConverter.toRelDataType(
                                        new ZonedTimestampType(3), typeFactory))
                .isInstanceOf(TableException.class)
                .hasMessageContaining("TIMESTAMP WITH TIME ZONE");
        assertThatThrownBy(
                        () ->
                                LogicalRelDataTypeConverter.toRelDataType(
                                        DistinctType.newBuilder(
                                                        ObjectIdentifier.of("cat", "db", "x"),
                                                        new IntType())
                                                .build(),
                                        typeFactory))
                .isInstanceOf(TableException.class)
                .hasMessageContaining("DISTINCT type");
    }
}

