/** Tests for {@link RexLiteralUtil#toFlinkInternalValue(Comparable, LogicalType)}. */
class RexLiteralUtilToFlinkInternalValueTests {

    @Test
    void convertsNullAndStringValues() {
        assertThat(RexLiteralUtil.toFlinkInternalValue(null, new VarCharType(20))).isNull();
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                new NlsString("flink", null, null), new VarCharType(20)))
                .isEqualTo(BinaryStringData.fromString("flink"));
        assertThat(RexLiteralUtil.toFlinkInternalValue("flink", new VarCharType(20)))
                .isEqualTo(BinaryStringData.fromString("flink"));
    }

    @Test
    void convertsBooleanBinaryUuidAndDecimalValues() {
        assertThat(RexLiteralUtil.toFlinkInternalValue(true, new BooleanType())).isEqualTo(true);
        byte[] bytes = new byte[] {1, 2, 3};
        assertThat(RexLiteralUtil.toFlinkInternalValue(new ByteString(bytes), new VarBinaryType(3)))
                .isEqualTo(bytes);

        UUID uuid = UUID.fromString("123e4567-e89b-12d3-a456-426614174000");
        assertThat(RexLiteralUtil.toFlinkInternalValue(uuid, new UuidType()))
                .isEqualTo(org.apache.flink.table.types.logical.utils.UuidUtils.toBytes(uuid));

        BigDecimal decimal = new BigDecimal("123.45");
        assertThat(RexLiteralUtil.toFlinkInternalValue(decimal, new DecimalType(10, 2)))
                .isEqualTo(DecimalData.fromBigDecimal(decimal, 10, 2));
    }

    @Test
    void convertsNumericValuesToTheLogicalTypeRepresentation() {
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                1.9d, new org.apache.flink.table.types.logical.TinyIntType()))
                .isEqualTo((byte) 1);
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                1.9d, new org.apache.flink.table.types.logical.SmallIntType()))
                .isEqualTo((short) 1);
        assertThat(RexLiteralUtil.toFlinkInternalValue(1L, new IntType())).isEqualTo(1);
        assertThat(RexLiteralUtil.toFlinkInternalValue(1, new BigIntType())).isEqualTo(1L);
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                1, new org.apache.flink.table.types.logical.FloatType()))
                .isEqualTo(1.0f);
        assertThat(RexLiteralUtil.toFlinkInternalValue(1, new DoubleType())).isEqualTo(1.0d);
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                14,
                                new YearMonthIntervalType(
                                        false, YearMonthIntervalType.YearMonthResolution.MONTH, 2)))
                .isEqualTo(14);
    }

    @Test
    void convertsDateAndTimestampValues() {
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue(
                                new DateString("1970-01-03"), new DateType()))
                .isEqualTo(2);
        TimestampString timestamp = new TimestampString("2024-01-02 03:04:05.678");
        LocalDateTime localDateTime = LocalDateTime.of(2024, 1, 2, 3, 4, 5, 678_000_000);
        assertThat(RexLiteralUtil.toFlinkInternalValue(timestamp, new TimestampType(3)))
                .isEqualTo(TimestampData.fromLocalDateTime(localDateTime));
        assertThat(RexLiteralUtil.toFlinkInternalValue(timestamp, new LocalZonedTimestampType(3)))
                .isEqualTo(
                        TimestampData.fromInstant(
                                localDateTime.toInstant(java.time.ZoneOffset.UTC)));
    }

    @Test
    void rejectsUnsupportedTypeAndUnexpectedValueClass() {
        assertThatThrownBy(
                        () -> RexLiteralUtil.toFlinkInternalValue(1, new ArrayType(new IntType())))
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("Type not supported");
        assertThatIllegalStateException()
                .isThrownBy(() -> RexLiteralUtil.toFlinkInternalValue(1, new VarCharType(10)))
                .withMessageContaining("Unexpected class");
    }
}

