/** Tests for the state and output transitions in {@link StreamingJoinOperator#processElement}. */
class StreamingJoinOperatorProcessElementTests {

    private static final InternalTypeInfo<RowData> ROW_TYPE =
            InternalTypeInfo.ofFields(new org.apache.flink.table.types.logical.IntType());

    @Test
    void accumulateOnInnerJoinStoresRecordAndEmitsMatchingRows() throws Exception {
        TestOperator operator = new TestOperator(false, false);
        RowData input = row(RowKind.INSERT, 1);
        RowData match = row(RowKind.INSERT, 1);
        JoinRecordStateView inputState = state();
        JoinRecordStateView otherState = state(match);
        operator.invoke(input, inputState, otherState, true, null);

        assertThat(operator.output).containsExactly(join(RowKind.INSERT, input, match));
        org.mockito.Mockito.verify(inputState).addRecord(input);
    }

    @Test
    void accumulateOnOuterJoinWithoutMatchEmitsNullPadding() throws Exception {
        TestOperator operator = new TestOperator(true, false);
        RowData input = row(RowKind.INSERT, 2);
        OuterJoinRecordStateView inputState = outerState();
        operator.invoke(input, inputState, state(), true, null);

        assertThat(operator.output).containsExactly(join(RowKind.INSERT, input, null));
        org.mockito.Mockito.verify(inputState).addRecord(input, 0);
    }

    @Test
    void retractOnInnerJoinEmitsDeleteForExistingMatch() throws Exception {
        TestOperator operator = new TestOperator(false, false);
        RowData input = row(RowKind.DELETE, 1);
        RowData match = row(RowKind.INSERT, 1);
        JoinRecordStateView inputState = state();
        operator.invoke(input, inputState, state(match), true, null);

        assertThat(operator.output).containsExactly(join(RowKind.DELETE, input, match));
        org.mockito.Mockito.verify(inputState).retractRecord(input);
    }

    @Test
    void retractOnOuterJoinWithoutMatchRemovesNullPadding() throws Exception {
        TestOperator operator = new TestOperator(true, false);
        RowData input = row(RowKind.DELETE, 2);
        OuterJoinRecordStateView inputState = outerState();
        operator.invoke(input, inputState, state(), true, null);

        assertThat(operator.output).containsExactly(join(RowKind.DELETE, input, null));
        org.mockito.Mockito.verify(inputState).retractRecord(input);
    }

    private static GenericRowData row(RowKind kind, int value) {
        GenericRowData row = new GenericRowData(1);
        row.setRowKind(kind);
        row.setField(0, value);
        return row;
    }

    private static RowData join(RowKind kind, RowData left, RowData right) {
        GenericRowData joined = new GenericRowData(2);
        joined.setRowKind(kind);
        joined.setField(0, left == null ? null : left.getInt(0));
        joined.setField(1, right == null ? null : right.getInt(0));
        return joined;
    }

    private static JoinRecordStateView state(RowData... records) throws Exception {
        JoinRecordStateView state = mock(JoinRecordStateView.class);
        when(state.getRecords()).thenReturn(Arrays.asList(records));
        return state;
    }

    private static OuterJoinRecordStateView outerState() throws Exception {
        OuterJoinRecordStateView state = mock(OuterJoinRecordStateView.class);
        when(state.getRecordsAndNumOfAssociations()).thenReturn(Collections.emptyList());
        return state;
    }

    private static final class TestOperator extends StreamingJoinOperator {
        private final List<RowData> output = new ArrayList<>();

        private TestOperator(boolean leftOuter, boolean rightOuter) {
            super(
                    ROW_TYPE,
                    ROW_TYPE,
                    new GeneratedJoinCondition(
                            "AlwaysTrueJoinCondition",
                            "public class AlwaysTrueJoinCondition extends "
                                    + "org.apache.flink.table.runtime.generated.JoinCondition { "
                                    + "public boolean apply(org.apache.flink.table.data.RowData l, "
                                    + "org.apache.flink.table.data.RowData r) { return "
                                    + "l.getInt(0) == r.getInt(0); } }",
                            new Object[0]),
                    JoinInputSideSpec.withoutUniqueKey(),
                    JoinInputSideSpec.withoutUniqueKey(),
                    leftOuter,
                    rightOuter,
                    null,
                    null,
                    false,
                    new boolean[] {false},
                    0,
                    0);
            setField("outRow", new JoinedRowData());
            setField("leftNullRow", new GenericRowData(1));
            setField("rightNullRow", new GenericRowData(1));
            collector =
                    new TimestampedCollector<>(
                            new Output<StreamRecord<RowData>>() {
                                @Override
                                public void close() {}

                                @Override
                                public void collect(StreamRecord<RowData> record) {
                                    output.add(copy(record.getValue()));
                                }

                                @Override
                                public <X> void collect(
                                        org.apache.flink.util.OutputTag<X> outputTag,
                                        StreamRecord<X> record) {}

                                @Override
                                public void emitWatermark(WatermarkEvent watermark) {}

                                @Override
                                public void emitWatermark(
                                        org.apache.flink.streaming.api.watermark.Watermark
                                                watermark) {}

                                @Override
                                public void emitRecordAttributes(
                                        RecordAttributes recordAttributes) {}

                                @Override
                                public void emitWatermarkStatus(WatermarkStatus watermarkStatus) {}

                                @Override
                                public void emitLatencyMarker(
                                        org.apache.flink.streaming.runtime.streamrecord
                                                        .LatencyMarker
                                                latencyMarker) {}
                            });
        }

        private void setField(String name, Object value) {
            try {
                Field field = StreamingJoinOperator.class.getDeclaredField(name);
                field.setAccessible(true);
                field.set(this, value);
            } catch (ReflectiveOperationException e) {
                throw new AssertionError(e);
