        private void invoke(
                RowData input,
                JoinRecordStateView inputState,
                JoinRecordStateView otherState,
                boolean inputIsLeft,
                RowData pairedRecord)
                throws Exception {
            JoinCondition condition = mock(JoinCondition.class);
            when(condition.apply(
                            org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any()))
                    .thenAnswer(
                            invocation -> {
                                RowData left = invocation.getArgument(0);
                                RowData right = invocation.getArgument(1);
                                return left.getInt(0) == right.getInt(0);
                            });
            joinCondition =
                    new JoinConditionWithNullFilters(
                            condition,
                            new boolean[0],
                            mock(org.apache.flink.streaming.api.operators.KeyContext.class));
            processElement(input, inputState, otherState, inputIsLeft, pairedRecord);
        }

        private static RowData copy(RowData row) {
            GenericRowData copy = new GenericRowData(2);
            copy.setRowKind(row.getRowKind());
            copy.setField(0, row.isNullAt(0) ? null : row.getInt(0));
            copy.setField(1, row.isNullAt(1) ? null : row.getInt(1));
            return copy;
        }
    }
